// IMPORTANT : ce patch corrige un probleme decouvert le 25/08 en fin de
// journee - le tout premier patch de ce matin (l'interstitiel avec
// recompense optionnel toutes les 5 parties) avait en realite ECHOUE
// silencieusement (erreur "Cannot find module" jamais suivie d'un nouvel
// essai reussi, contrairement a tous les patchs suivants). Verifie
// directement sur GitHub : les fichiers n'existaient pas, l'appli tournait
// encore avec l'ancienne pub FORCEE toutes les 5 parties depuis ce matin.
// Ce patch livre (enfin) cette fonctionnalite pour de vrai.
//
// Il corrige aussi un vrai bug signale aujourd'hui : "2 pubs sans video
// comptabilisees, pas de recompense". Cause reelle : le bouton "regarder
// une pub" de la Boutique et ceux ajoutes plus tard dans Profil/Reglages
// tenaient chacun leur PROPRE copie independante du compteur quotidien -
// si deux ecrans avec un bouton pub etaient ouverts en meme temps, les deux
// copies pouvaient se desynchroniser et faire monter le compteur sans
// recompense. Corrige avec une seule source de verite partagee
// (AdBudgetProvider) utilisee partout.
//
// Pas de nouvelle dependance JS, part par eas update, pas besoin de nouveau
// build.
//
// A appliquer depuis la racine du repo OU depuis strikr-app :
//   node patch-real-rewarded-interstitial.js
//   git add -A
//   git commit -m "Livre enfin l'interstitiel avec recompense et corrige le compteur de pubs desynchronise"
//   git push -u origin main
//   cd strikr-app
//   eas update --branch production --platform ios
//   eas update --branch production --platform android

const fs = require('fs');
const path = require('path');

function resolveBase() {
  const candidates = [path.join(__dirname, 'strikr-app'), __dirname];
  for (const c of candidates) {
    if (fs.existsSync(path.join(c, 'package.json')) && fs.existsSync(path.join(c, 'App.tsx'))) {
      return c;
    }
  }
  throw new Error(
    "Impossible de trouver le dossier strikr-app (avec package.json et App.tsx dedans). " +
    "Lance ce script depuis la racine du repo (a cote du dossier strikr-app) ou depuis l'interieur de strikr-app."
  );
}
const BASE = resolveBase();
console.log('dossier detecte :', BASE);

function write(rel, content) {
  const full = path.join(BASE, rel);
  fs.mkdirSync(path.dirname(full), { recursive: true });
  fs.writeFileSync(full, content);
  console.log('wrote', rel);
}

function remove(rel) {
  const full = path.join(BASE, rel);
  if (fs.existsSync(full)) {
    fs.unlinkSync(full);
    console.log('removed', rel, '(remplace par adBudget.tsx)');
  }
}

write("src/lib/ads.ts", "// Ad adapter — the only place that should know how ads are actually shown.\n// Everything else (ShopScreen, useInterstitialAd) calls these two functions\n// and doesn't care about the AdMob SDK details.\nimport { Platform } from 'react-native';\nimport type {\n  AdsConsentStatus as AdsConsentStatusT,\n  InterstitialAd as InterstitialAdT,\n  RewardedAd as RewardedAdT,\n  RewardedInterstitialAd as RewardedInterstitialAdT,\n} from 'react-native-google-mobile-ads';\nimport { supabase } from './supabase';\n\n// react-native-google-mobile-ads' Android native code doesn't compile under\n// this app's Old Architecture config (newArchEnabled: false) — its Kotlin\n// package references a TurboModule spec class that only exists when\n// codegen runs, which it doesn't here. The one documented way to exclude\n// just the Android side (react-native.config.js, platforms.android = null)\n// turned out to be unreliable with Expo's autolinking in practice, so it's\n// not used. This iOS-only diagnostic round therefore must not be built or\n// updated for Android (--platform ios only) until that's solved\n// separately — an Android build would hit the same Kotlin compile error\n// again. This JS-level platform gate keeps Android from even importing the\n// module, in case a stale Android binary somehow loads this bundle.\nconst IS_ANDROID = Platform.OS === 'android';\n// eslint-disable-next-line @typescript-eslint/no-var-requires\nconst GMA = IS_ANDROID ? null : (require('react-native-google-mobile-ads') as typeof import('react-native-google-mobile-ads'));\nconst mobileAds = GMA?.default;\nconst AdEventType = GMA?.AdEventType;\nconst AdsConsent = GMA?.AdsConsent;\nconst AdsConsentStatus = GMA?.AdsConsentStatus as typeof AdsConsentStatusT | undefined;\nconst InterstitialAd = GMA?.InterstitialAd;\nconst RewardedAd = GMA?.RewardedAd;\nconst RewardedAdEventType = GMA?.RewardedAdEventType;\nconst RewardedInterstitialAd = GMA?.RewardedInterstitialAd;\n\n// Diagnostic conclusion from an earlier round: swapping to Google's own\n// test ad units made no difference — the crash reproduced identically —\n// which rules out our AdMob account/ad units as the cause. Real ones below.\n//\n// Root cause, step 1 (Aug 2026): this is an upstream React Native bug on\n// iOS 26 release builds, unrelated to AdMob specifically — see\n// facebook/react-native#54859 and #53960. An async \"void\" TurboModule\n// method that throws an NSException gets funneled through\n// convertNSExceptionToJSError() from a background native queue, which\n// touches jsi::Runtime off the JS thread and crashes. A 3-line fix exists\n// upstream (not yet in a released React Native/Expo version) — applied\n// here via patches/react-native+0.81.5.patch (patch-package).\n//\n// Root cause, step 2: that fix alone wasn't enough — build 40's real crash\n// log (SIGABRT, \"objc_exception_rethrow\" -> uncaught -> terminate) showed\n// the patch working exactly as designed (no more memory corruption), but\n// nothing catches the re-thrown exception either, so the app still aborts.\n//\n// Root cause, step 3 (dead end): theorized the exception came from\n// react-native-google-mobile-ads' iOS EventEmitter bridge specifically,\n// since their README's New Architecture status table lists iOS\n// \"EventEmitter (Turbo Native Module)\" as \"To-Do\", and Full Screen Ads\n// only moved onto that path in v14.5.0 (2024-12-03). Pinned the library\n// to 14.4.3 (the last version before that migration) to test it — build\n// 41's crash log was byte-for-byte the same crash signature. Ruled out:\n// the library version doesn't matter, so the exception isn't coming from\n// that specific migration. Whatever throws it, it's happening at a layer\n// this app's code can't reach or catch (matches newArchEnabled:false\n// already not helping either, from the very first diagnostic pass).\n//\n// Root cause, step 4 (new lead, untested): the app never implemented the\n// User Messaging Platform (UMP) consent flow Google requires for EEA\n// users before requesting ads — our tester is in France, squarely EEA.\n// Google's own SDK is known to behave unpredictably (including crash\n// reports for consent-related bugs on iOS, e.g.\n// googleads-mobile-unity#2617) when an ad is requested without consent\n// having been gathered first. This is unrelated to the TurboModule\n// theory entirely, and — unlike the RN patch and the library downgrade —\n// hasn't been tried yet. Consent gathering is now wired into\n// ensureAdsInitialized() below, before mobileAds().initialize().\n//\n// Root cause, step 5 (Expo support reply, Aug 2026) — the real one:\n// step 1's whole premise was wrong. newArchEnabled is false in app.json,\n// so the New Architecture TurboModule code the RN patch targeted was\n// never even running — that's exactly why patching it changed nothing.\n// com.facebook.react.ExceptionsManagerQueue is React Native's *legacy*\n// bridge ExceptionsManager: in a release build, an uncaught JS exception\n// thrown inside a native-invoked callback gets rethrown as a native\n// RCTFatalException and aborts the app. So this was always a plain,\n// catchable bug in our own JS, not an unfixable native/iOS 26 issue. See\n// the fix at showRewardedAd()/showInterstitialAd() below (in-flight guard\n// + try/catch around show()) for the concrete bug this most likely was.\n//\n// Root cause, step 6 (confirmed, Aug 2026) — found it, in this app's own\n// code, by reading react-native-google-mobile-ads' actual source: this\n// file used AdEventType.LOADED for the rewarded ad's LOADED listener, but\n// RewardedAd.addAdEventListener() explicitly throws for that (\"use\n// RewardedAdEventType.LOADED instead\") — so on every single rewarded-ad\n// attempt, that registration call threw immediately, before current.load()\n// ever ran. LOAD_TIMEOUT (below) had already been scheduled one line\n// earlier though, and setTimeout doesn't care that the function that\n// scheduled it threw right after — 15s later it fired regardless, called\n// finish(), which tried to invoke unsub* functions that were never\n// assigned because registration never completed. That uncaught throw, from\n// an orphaned native timer callback with nothing wrapping it, is what\n// actually aborted the app every time — 100% reproducible, independent of\n// ad units/library version/consent, matching everything observed. Fixed\n// below (RewardedAdEventType.LOADED); the registration block is now also\n// wrapped so a future mistake here fails safe instead of orphaning the\n// timeout again.\n// Confirmed working end to end with Google's test units (consent, init,\n// load, LOADED, show, EARNED_REWARD, CLOSED, finish — no crash). Back to\n// real units: the crash was never tied to which ad unit was used (an\n// earlier diagnostic round already showed test units crashing identically,\n// which is what pointed away from AdMob and toward our own JS in the first\n// place), so this is safe. Real units currently no-fill until the app is\n// publicly listed — handled gracefully (round just continues without an\n// ad), not a bug.\nconst USE_TEST_ADS = false;\n\nconst REAL_AD_UNIT_IDS = {\n  rewarded: 'ca-app-pub-7516626754240121/7450570987',\n  interstitial: 'ca-app-pub-7516626754240121/2333975671',\n  rewardedInterstitial: 'ca-app-pub-7516626754240121/5647175354',\n};\n\n// Google's official, permanent test ad units — same for every developer,\n// documented at https://developers.google.com/admob/ios/test-ads.\nconst TEST_AD_UNIT_IDS = {\n  rewarded: 'ca-app-pub-3940256099942544/1712485313',\n  interstitial: 'ca-app-pub-3940256099942544/4411468910',\n  rewardedInterstitial: 'ca-app-pub-3940256099942544/6978759866',\n};\n\nexport const AD_UNIT_IDS = USE_TEST_ADS ? TEST_AD_UNIT_IDS : REAL_AD_UNIT_IDS;\n\n// Safety net: if AdMob never fires LOADED or ERROR (seen in practice —\n// ad inventory can be unreliable before the app is publicly listed), the\n// caller would otherwise await forever and the \"watch an ad\" button would\n// stay stuck on its loading spinner permanently.\nconst LOAD_TIMEOUT = 15000;\n\n// Expo support (Sarah) traced the fatal crash to errors thrown *inside*\n// AdEventType listener callbacks — load() returns nothing (not a promise),\n// so a \"no fill\"/error surfaces later as a native event, off the call\n// stack of anything wrapped in try/catch above. Her suggested test: catch\n// and log inside the listener itself. Without a Mac/Console.app on hand,\n// console.warn alone would be invisible on a released build, so this also\n// writes to Supabase — best-effort, and it must never itself throw from\n// inside a native-invoked callback.\nfunction reportAdError(context: string, error: unknown) {\n  console.warn(`[ads] ${context}`, error);\n  try {\n    const err = error as { message?: string; stack?: string } | undefined;\n    supabase.auth\n      .getSession()\n      .then(({ data }) => {\n        const userId = data.session?.user?.id;\n        if (!userId) return;\n        return supabase.from('app_events').insert({\n          user_id: userId,\n          event_name: 'ad_error_diagnostic',\n          properties: { context, message: err?.message ?? String(error), stack: err?.stack?.slice(0, 1000) },\n        });\n      })\n      .then(() => {});\n  } catch {\n    // Reporting is best-effort only.\n  }\n}\n\n// The native SDK must finish initializing before any ad object is created.\n// This used to be created eagerly at module import time (`let rewarded =\n// RewardedAd.createForAdRequest(...)` right here at the top level) — but\n// JS module imports are all evaluated before an importing module's own\n// top-level code runs, so that eager creation actually happened *before*\n// App.tsx's own mobileAds().initialize() call ever had a chance to fire.\n// That leaves the ad object wired to a not-yet-ready native SDK, which\n// lines up with a crash reproducing identically on every real ad attempt\n// — even with Google's own guaranteed-valid test ad units, which rules out\n// our AdMob account/ad units as the cause. Ad objects are now created\n// lazily, only after this promise actually resolves.\nlet initPromise: Promise<unknown> | null = null;\nexport function ensureAdsInitialized() {\n  if (!initPromise) {\n    initPromise = (async () => {\n      // Gather EEA consent before initializing the SDK, per Google's\n      // documented flow — never implemented before now. If this fails for\n      // any reason, still initialize rather than leave ads permanently\n      // broken; worst case the SDK falls back to non-personalized ads.\n      try {\n        const consentInfo = await AdsConsent.requestInfoUpdate();\n        if (\n          consentInfo.isConsentFormAvailable &&\n          (consentInfo.status === AdsConsentStatus.REQUIRED || consentInfo.status === AdsConsentStatus.UNKNOWN)\n        ) {\n          await AdsConsent.showForm();\n        }\n      } catch (e) {\n        console.warn('AdsConsent gathering failed', e);\n      }\n      // Same reasoning as show()/load() below: this promise is awaited\n      // directly by showRewardedAd()/showInterstitialAd() with nothing\n      // catching a rejection on their end, so a failure here must not\n      // reject either — it would otherwise surface as an unhandled\n      // promise rejection, which is exactly the kind of uncaught JS\n      // exception step 5 in the history above says gets rethrown as a\n      // fatal native crash in production.\n      try {\n        await mobileAds().initialize();\n      } catch (e) {\n        console.warn('mobileAds().initialize() failed', e);\n      }\n    })();\n  }\n  return initPromise;\n}\n\n// Each ad object is single-use (load → show → gone), so a fresh one is\n// created after every show() to have the next ad ready to load.\nlet rewarded: RewardedAdT | null = null;\nlet interstitial: InterstitialAdT | null = null;\nlet rewardedInterstitial: RewardedInterstitialAdT | null = null;\n\n// Root cause, step 5 (Expo support, Aug 2026): steps 1-4 above chased the\n// wrong layer entirely — newArchEnabled is false in app.json, so the\n// TurboModule/New-Architecture theory in step 1 never applied here in the\n// first place (that's *why* the RN patch changed nothing: the code it\n// patched was never running). Expo support traced\n// com.facebook.react.ExceptionsManagerQueue to React Native's *legacy*\n// bridge: in a release build, any uncaught JS exception thrown inside a\n// native-invoked callback (e.g. an AdEventType listener) gets rethrown as\n// a native RCTFatalException and aborts the whole app — this is an\n// ordinary, catchable bug in our own JS, not an unfixable native/iOS 26\n// issue.\n//\n// showRewardedAd() has two independent callers (ShopScreen's \"watch an\n// ad\" button and useGameEngine's doubleReward) that each only guard\n// against re-entering *themselves* — neither knows about the other. If\n// one call is abandoned mid-flight (e.g. leaving Shop before its ad\n// resolves) while `rewarded` still points at that same not-yet-settled\n// ad object, a second call from the other caller reuses it instead of a\n// fresh instance, so two independent LOADED listeners can both end up\n// calling show() on the same ad — calling show() twice on one ad is a\n// documented way to make AdMob's SDK throw. rewardedInFlight below\n// closes that gap: a second concurrent call fails immediately instead of\n// sharing state with one already in progress. current.show() is also now\n// wrapped in try/catch so that if it (or anything else here) throws for\n// any reason at all, the round just continues without an ad — matching\n// the app's own stated philosophy — instead of taking the whole app down.\nlet rewardedInFlight = false;\nlet interstitialInFlight = false;\nlet rewardedInterstitialInFlight = false;\n\nfunction freshRewarded(): RewardedAdT {\n  rewarded = RewardedAd.createForAdRequest(AD_UNIT_IDS.rewarded);\n  return rewarded;\n}\n\nfunction freshInterstitial(): InterstitialAdT {\n  interstitial = InterstitialAd.createForAdRequest(AD_UNIT_IDS.interstitial);\n  return interstitial;\n}\n\nfunction freshRewardedInterstitial(): RewardedInterstitialAdT {\n  rewardedInterstitial = RewardedInterstitialAd.createForAdRequest(AD_UNIT_IDS.rewardedInterstitial);\n  return rewardedInterstitial;\n}\n\n// The first attempt at this fix only wrapped show() in try/catch, and\n// still crashed with the byte-for-byte identical signature. That means\n// something else in this chain throws too — createForAdRequest(), load(),\n// or mobileAds().initialize() rejecting up through the unguarded `await\n// ensureAdsInitialized()` below, any of which becomes an unhandled\n// promise rejection with no caller-side try/catch (ShopScreen,\n// useGameEngine, useInterstitialAd all just do a bare `await\n// showRewardedAd()`/`showInterstitialAd()`). So instead of guessing which\n// specific call is the one that throws, everything in both functions now\n// runs inside one top-level try/catch each: whatever happens, the\n// returned promise always resolves, never rejects.\nexport async function showRewardedAd(): Promise<{ success: boolean }> {\n  if (rewardedInFlight) return { success: false };\n  rewardedInFlight = true;\n  try {\n    await ensureAdsInitialized();\n    return await new Promise<{ success: boolean }>((resolve) => {\n      let settled = false;\n      const finish = (success: boolean) => {\n        if (settled) return;\n        settled = true;\n        clearTimeout(timeout);\n        unsubEarned();\n        unsubLoaded();\n        unsubClosed();\n        unsubError();\n        try {\n          freshRewarded();\n        } catch (e) {\n          console.warn('freshRewarded() threw', e);\n        }\n        rewardedInFlight = false;\n        resolve({ success });\n      };\n      let current: RewardedAdT;\n      try {\n        current = rewarded || freshRewarded();\n      } catch (e) {\n        console.warn('RewardedAd.createForAdRequest() threw', e);\n        rewardedInFlight = false;\n        resolve({ success: false });\n        return;\n      }\n      let earned = false;\n      // The real bug behind every previous crash, found by actually reading\n      // this library's source: RewardedAd.addAdEventListener() throws\n      // synchronously if given AdEventType.LOADED instead of its own\n      // RewardedAdEventType.LOADED — a mistake this file made below for a\n      // long time. That throw happens *before* current.load() is ever\n      // reached, but LOAD_TIMEOUT was already scheduled one line above and\n      // keeps running regardless — 15s later it fires finish(), which tries\n      // to call unsub* functions that were never assigned, and *that*\n      // uncaught throw (from an orphaned native timer callback, outside any\n      // try/catch) is what actually crashed the app every single time.\n      // unsubEarned/Loaded/Closed/Error now default to no-ops and the whole\n      // registration block is guarded, so even a future mistake here can't\n      // orphan the timeout the same way again.\n      const timeout = setTimeout(() => {\n        try {\n          finish(false);\n        } catch (e) {\n          reportAdError('rewarded.LOAD_TIMEOUT finish()', e);\n        }\n      }, LOAD_TIMEOUT);\n      let unsubEarned = () => {};\n      let unsubLoaded = () => {};\n      let unsubClosed = () => {};\n      let unsubError = () => {};\n      try {\n        unsubEarned = current.addAdEventListener(RewardedAdEventType.EARNED_REWARD, () => {\n          try {\n            earned = true;\n          } catch (e) {\n            reportAdError('rewarded.EARNED_REWARD', e);\n          }\n        });\n        unsubLoaded = current.addAdEventListener(RewardedAdEventType.LOADED, () => {\n          // LOAD_TIMEOUT exists to catch an ad that never loads — once it\n          // has loaded and is about to show, that's no longer a risk, but\n          // the timer kept running regardless (it was only ever cleared\n          // from inside finish()). A rewarded video commonly runs longer\n          // than LOAD_TIMEOUT's 15s, so the timeout would fire mid-playback\n          // and settle this as a failure — silently losing a reward the\n          // player was about to legitimately earn a moment later, since\n          // finish() is a no-op once already settled. Clearing it here,\n          // the instant the ad is confirmed loaded, closes that gap.\n          clearTimeout(timeout);\n          try {\n            current.show();\n          } catch (e) {\n            reportAdError('rewarded.LOADED show()', e);\n            finish(false);\n          }\n        });\n        unsubClosed = current.addAdEventListener(AdEventType.CLOSED, () => {\n          try {\n            finish(earned);\n          } catch (e) {\n            reportAdError('rewarded.CLOSED finish()', e);\n          }\n        });\n        unsubError = current.addAdEventListener(AdEventType.ERROR, (error: unknown) => {\n          reportAdError('rewarded.ERROR', error);\n          try {\n            finish(false);\n          } catch (e) {\n            reportAdError('rewarded.ERROR finish()', e);\n          }\n        });\n      } catch (e) {\n        reportAdError('rewarded.addAdEventListener', e);\n      }\n      try {\n        current.load();\n      } catch (e) {\n        console.warn('RewardedAd.load() threw', e);\n        finish(false);\n      }\n    });\n  } catch (e) {\n    console.warn('showRewardedAd() failed', e);\n    rewardedInFlight = false;\n    return { success: false };\n  }\n}\n\nexport async function showInterstitialAd(): Promise<void> {\n  if (interstitialInFlight) return;\n  interstitialInFlight = true;\n  try {\n    await ensureAdsInitialized();\n    return await new Promise<void>((resolve) => {\n      let settled = false;\n      const finish = () => {\n        if (settled) return;\n        settled = true;\n        clearTimeout(timeout);\n        unsubLoaded();\n        unsubClosed();\n        unsubError();\n        try {\n          freshInterstitial();\n        } catch (e) {\n          console.warn('freshInterstitial() threw', e);\n        }\n        interstitialInFlight = false;\n        resolve();\n      };\n      let current: InterstitialAdT;\n      try {\n        current = interstitial || freshInterstitial();\n      } catch (e) {\n        console.warn('InterstitialAd.createForAdRequest() threw', e);\n        interstitialInFlight = false;\n        resolve();\n        return;\n      }\n      // Same orphaned-timeout guard as showRewardedAd() above: if the\n      // registration block below ever throws, unsub* stay no-ops and\n      // finish() (called from this timeout in 15s regardless) can't crash\n      // trying to call an unassigned unsub function.\n      const timeout = setTimeout(() => {\n        try {\n          finish();\n        } catch (e) {\n          reportAdError('interstitial.LOAD_TIMEOUT finish()', e);\n        }\n      }, LOAD_TIMEOUT);\n      let unsubLoaded = () => {};\n      let unsubClosed = () => {};\n      let unsubError = () => {};\n      try {\n        unsubLoaded = current.addAdEventListener(AdEventType.LOADED, () => {\n          // Same reasoning as showRewardedAd() above: clear the load\n          // timeout the instant the ad is loaded, or it can fire mid-view\n          // and finish() the round early while the ad is still on screen.\n          clearTimeout(timeout);\n          try {\n            current.show();\n          } catch (e) {\n            reportAdError('interstitial.LOADED show()', e);\n            finish();\n          }\n        });\n        unsubClosed = current.addAdEventListener(AdEventType.CLOSED, () => {\n          try {\n            finish();\n          } catch (e) {\n            reportAdError('interstitial.CLOSED finish()', e);\n          }\n        });\n        // Failing to load a real ad shouldn't block the game — the round\n        // just continues without an interstitial that round.\n        unsubError = current.addAdEventListener(AdEventType.ERROR, (error: unknown) => {\n          reportAdError('interstitial.ERROR', error);\n          try {\n            finish();\n          } catch (e) {\n            reportAdError('interstitial.ERROR finish()', e);\n          }\n        });\n      } catch (e) {\n        reportAdError('interstitial.addAdEventListener', e);\n      }\n      try {\n        current.load();\n      } catch (e) {\n        console.warn('InterstitialAd.load() threw', e);\n        finish();\n      }\n    });\n  } catch (e) {\n    console.warn('showInterstitialAd() failed', e);\n    interstitialInFlight = false;\n  }\n}\n\n// Shown at the same \"every 5 rounds\" checkpoint the old forced interstitial\n// used (see useInterstitialAd.ts / RewardedInterstitialModal.tsx) — the\n// player is offered a reward for watching instead of being forced through\n// an ad with nothing in return, and can decline and continue for free.\n// Same shape and same lessons already learned from showRewardedAd() above:\n// RewardedAdEventType.LOADED (not AdEventType.LOADED, which this ad type\n// also throws for), the load timeout cleared the instant the ad loads (or\n// it can fire mid-view and lose an otherwise-earned reward), and every\n// listener registration guarded so a mistake here fails safe.\nexport async function showRewardedInterstitialAd(): Promise<{ success: boolean }> {\n  if (rewardedInterstitialInFlight) return { success: false };\n  rewardedInterstitialInFlight = true;\n  try {\n    await ensureAdsInitialized();\n    return await new Promise<{ success: boolean }>((resolve) => {\n      let settled = false;\n      const finish = (success: boolean) => {\n        if (settled) return;\n        settled = true;\n        clearTimeout(timeout);\n        unsubEarned();\n        unsubLoaded();\n        unsubClosed();\n        unsubError();\n        try {\n          freshRewardedInterstitial();\n        } catch (e) {\n          console.warn('freshRewardedInterstitial() threw', e);\n        }\n        rewardedInterstitialInFlight = false;\n        resolve({ success });\n      };\n      let current: RewardedInterstitialAdT;\n      try {\n        current = rewardedInterstitial || freshRewardedInterstitial();\n      } catch (e) {\n        console.warn('RewardedInterstitialAd.createForAdRequest() threw', e);\n        rewardedInterstitialInFlight = false;\n        resolve({ success: false });\n        return;\n      }\n      let earned = false;\n      const timeout = setTimeout(() => {\n        try {\n          finish(false);\n        } catch (e) {\n          reportAdError('rewardedInterstitial.LOAD_TIMEOUT finish()', e);\n        }\n      }, LOAD_TIMEOUT);\n      let unsubEarned = () => {};\n      let unsubLoaded = () => {};\n      let unsubClosed = () => {};\n      let unsubError = () => {};\n      try {\n        unsubEarned = current.addAdEventListener(RewardedAdEventType.EARNED_REWARD, () => {\n          try {\n            earned = true;\n          } catch (e) {\n            reportAdError('rewardedInterstitial.EARNED_REWARD', e);\n          }\n        });\n        unsubLoaded = current.addAdEventListener(RewardedAdEventType.LOADED, () => {\n          clearTimeout(timeout);\n          try {\n            current.show();\n          } catch (e) {\n            reportAdError('rewardedInterstitial.LOADED show()', e);\n            finish(false);\n          }\n        });\n        unsubClosed = current.addAdEventListener(AdEventType.CLOSED, () => {\n          try {\n            finish(earned);\n          } catch (e) {\n            reportAdError('rewardedInterstitial.CLOSED finish()', e);\n          }\n        });\n        unsubError = current.addAdEventListener(AdEventType.ERROR, (error: unknown) => {\n          reportAdError('rewardedInterstitial.ERROR', error);\n          try {\n            finish(false);\n          } catch (e) {\n            reportAdError('rewardedInterstitial.ERROR finish()', e);\n          }\n        });\n      } catch (e) {\n        reportAdError('rewardedInterstitial.addAdEventListener', e);\n      }\n      try {\n        current.load();\n      } catch (e) {\n        console.warn('RewardedInterstitialAd.load() threw', e);\n        finish(false);\n      }\n    });\n  } catch (e) {\n    console.warn('showRewardedInterstitialAd() failed', e);\n    rewardedInterstitialInFlight = false;\n    return { success: false };\n  }\n}\n");
write("src/data/shop.ts", "// Diamond packages for the shop. `id` must match the product identifier\n// registered on both App Store Connect and Google Play Console exactly —\n// react-native-iap requests products by this string (see src/lib/iap.ts).\n\n// AdMob diagnostic round (Aug 2026) — react-native-google-mobile-ads is\n// back after Expo support (Sarah) traced the iOS crash to errors thrown\n// inside AdEventType listener callbacks, off the call stack of every\n// try/catch added in earlier rounds (full history in src/lib/ads.ts).\n// ads.ts now wraps each listener body in its own try/catch and reports\n// whatever it catches to Supabase (app_events, event_name\n// 'ad_error_diagnostic'/'js_global_error') so it's readable without a Mac.\n// ADS_LIVE is true so this path actually runs — per Sarah's own advice,\n// only via a TestFlight build, not a full production release. The\n// separate Android native-compile failure under this app's Old\n// Architecture config is untouched by any of this, so this round is\n// iOS-only: build/update with --platform ios, never android or all.\nexport const ADS_LIVE = true;\n\n// Real purchases: Paid Apps Agreement signed, banking + tax info done on\n// both App Store Connect and AdMob, and the 4 IAP products exist there\n// (pack_s, pack_m, pack_l, pack_xxl matching SHOP_PACKAGES below). Live now\n// so the real Boutique UI (and its packs) can be screenshotted for each\n// product's required App Store Connect review image. Independent of\n// ADS_LIVE (ads and purchases activate separately).\nexport const MONETIZATION_LIVE = true;\n\nexport interface ShopPackage {\n  id: string;\n  diamonds: number;\n  bonus?: number;\n  priceLabel: string;\n  popular?: boolean;\n}\n\nexport const SHOP_PACKAGES: ShopPackage[] = [\n  { id: 'pack_s', diamonds: 100, priceLabel: '0,99 €' },\n  { id: 'pack_m', diamonds: 350, bonus: 30, priceLabel: '2,99 €', popular: true },\n  { id: 'pack_l', diamonds: 900, bonus: 120, priceLabel: '6,99 €' },\n  { id: 'pack_xxl', diamonds: 2000, bonus: 400, priceLabel: '14,99 €' },\n];\n\nexport const REWARDED_AD_DIAMONDS = 15;\nexport const REWARDED_AD_PER_DAY = 10;\n\n// Every Nth round, instead of a forced interstitial with nothing in return,\n// the player is offered a rewarded interstitial (see RewardedInterstitialModal)\n// — accept and watch for +REWARDED_INTERSTITIAL_DIAMONDS, or decline and\n// continue for free. No daily cap: it's opt-in, so there's no forced-view\n// quota to protect the way REWARDED_AD_PER_DAY does for the Shop's button.\nexport const INTERSTITIAL_EVERY_N_GAMES = 5;\nexport const REWARDED_INTERSTITIAL_DIAMONDS = 10;\n");
write("src/state/rewardedInterstitial.tsx", "// Global \"every 5 rounds\" ad checkpoint. Replaces the old unconditional\n// forced interstitial with an opt-in rewarded interstitial: any screen's\n// useInterstitialAd().recordRoundPlayed() calls offer() here instead of\n// showing an ad directly, and the single globally-mounted\n// RewardedInterstitialModal (see App.tsx) reads this same state to show the\n// prompt — so every screen gets the identical prompt without each of them\n// needing to render its own modal.\nimport React, { createContext, useCallback, useContext, useRef, useState } from 'react';\n\ninterface RewardedInterstitialContextValue {\n  visible: boolean;\n  offer: (onDone: () => void) => void;\n  resolve: () => void;\n}\n\nconst RewardedInterstitialContext = createContext<RewardedInterstitialContextValue | null>(null);\n\nexport function RewardedInterstitialProvider({ children }: { children: React.ReactNode }) {\n  const [visible, setVisible] = useState(false);\n  const pendingRef = useRef<(() => void) | null>(null);\n\n  const offer = useCallback((onDone: () => void) => {\n    pendingRef.current = onDone;\n    setVisible(true);\n  }, []);\n\n  // Called by the modal exactly once per offer() — whether the player\n  // declined immediately, watched and earned the reward, or the ad failed\n  // to load. Matches the contract the old direct showInterstitialAd().then()\n  // call had: onDone always eventually fires.\n  const resolve = useCallback(() => {\n    setVisible(false);\n    const cb = pendingRef.current;\n    pendingRef.current = null;\n    if (cb) cb();\n  }, []);\n\n  return (\n    <RewardedInterstitialContext.Provider value={{ visible, offer, resolve }}>\n      {children}\n    </RewardedInterstitialContext.Provider>\n  );\n}\n\nexport function useRewardedInterstitial() {\n  const ctx = useContext(RewardedInterstitialContext);\n  if (!ctx) throw new Error('useRewardedInterstitial must be used within RewardedInterstitialProvider');\n  return ctx;\n}\n");
write("src/components/RewardedInterstitialModal.tsx", "import React, { useState } from 'react';\nimport { ActivityIndicator, Modal, Pressable, Text, View } from 'react-native';\nimport { useTheme } from '../theme/ThemeContext';\nimport { useI18n } from '../i18n/i18n';\nimport { useRewardedInterstitial } from '../state/rewardedInterstitial';\nimport { useDiamonds } from '../state/diamonds';\nimport { showRewardedInterstitialAd } from '../lib/ads';\nimport { REWARDED_INTERSTITIAL_DIAMONDS } from '../data/shop';\nimport HardShadowBox from './HardShadowBox';\n\n// Mounted once at the app root (see App.tsx) — the opt-in replacement for\n// the old forced \"every 5 rounds\" interstitial (see\n// src/state/rewardedInterstitial.tsx for how any screen triggers this same\n// prompt). The player can always decline and continue for free; nothing\n// here ever blocks the game the way a forced interstitial did.\nexport default function RewardedInterstitialModal() {\n  const { colors, accent, fonts } = useTheme();\n  const { t } = useI18n();\n  const { visible, resolve } = useRewardedInterstitial();\n  const { addDiamonds } = useDiamonds();\n  const [watching, setWatching] = useState(false);\n\n  const decline = () => {\n    if (watching) return;\n    resolve();\n  };\n\n  const watch = async () => {\n    if (watching) return;\n    setWatching(true);\n    const { success } = await showRewardedInterstitialAd();\n    setWatching(false);\n    if (success) addDiamonds(REWARDED_INTERSTITIAL_DIAMONDS);\n    resolve();\n  };\n\n  return (\n    <Modal visible={visible} transparent animationType=\"fade\" onRequestClose={decline}>\n      <View style={{ flex: 1, backgroundColor: 'rgba(0,0,0,.5)', alignItems: 'center', justifyContent: 'center', padding: 24 }}>\n        <HardShadowBox bg={colors.card} shadowColor={colors.border} radius={20} offset={5}>\n          <View style={{ padding: 26, alignItems: 'center', maxWidth: 300 }}>\n            <Text style={{ fontSize: 38 }}>📺</Text>\n            <Text style={{ fontFamily: fonts.display, fontSize: 18, color: colors.ink, marginTop: 10, textAlign: 'center' }}>\n              {t('rewarded_interstitial_title')}\n            </Text>\n            <Text style={{ fontFamily: fonts.bodySemibold, fontSize: 13, color: colors.muted, marginTop: 6, textAlign: 'center' }}>\n              {t('rewarded_interstitial_body')}\n            </Text>\n            <View style={{ marginTop: 14, paddingVertical: 6, paddingHorizontal: 14, backgroundColor: accent.mint, borderRadius: 999 }}>\n              <Text style={{ fontFamily: fonts.displayBold, fontSize: 14, color: '#1a1a1a' }}>+{REWARDED_INTERSTITIAL_DIAMONDS} 💎</Text>\n            </View>\n            <Pressable\n              onPress={watch}\n              disabled={watching}\n              style={{\n                marginTop: 20, paddingVertical: 12, paddingHorizontal: 28, backgroundColor: accent.coral,\n                borderRadius: 12, opacity: watching ? 0.7 : 1, minWidth: 190, alignItems: 'center',\n              }}\n            >\n              {watching ? (\n                <ActivityIndicator color=\"#fff\" />\n              ) : (\n                <Text style={{ fontFamily: fonts.displayBold, fontSize: 13, color: '#fff' }}>{t('rewarded_interstitial_watch')}</Text>\n              )}\n            </Pressable>\n            <Pressable onPress={decline} disabled={watching} style={{ marginTop: 10, paddingVertical: 8 }}>\n              <Text style={{ fontFamily: fonts.bodySemibold, fontSize: 12, color: colors.muted }}>{t('rewarded_interstitial_decline')}</Text>\n            </Pressable>\n          </View>\n        </HardShadowBox>\n      </View>\n    </Modal>\n  );\n}\n");
write("src/game/useInterstitialAd.ts", "import { useCallback } from 'react';\nimport AsyncStorage from '@react-native-async-storage/async-storage';\nimport { ADS_LIVE, INTERSTITIAL_EVERY_N_GAMES } from '../data/shop';\nimport { useRewardedInterstitial } from '../state/rewardedInterstitial';\n\nconst STORAGE_KEY = 'strikr_games_played_v1';\n\nexport function useInterstitialAd() {\n  const { offer } = useRewardedInterstitial();\n\n  // Called at the end of every round (win or loss). Runs `onContinue`\n  // immediately unless this round is the Nth, in which case the player is\n  // offered a rewarded interstitial (see RewardedInterstitialModal) instead\n  // of a forced ad — `onContinue` fires once they've either watched it or\n  // declined. Skipped entirely while ads aren't live.\n  const recordRoundPlayed = useCallback(\n    (onContinue: () => void) => {\n      if (!ADS_LIVE) {\n        onContinue();\n        return;\n      }\n      AsyncStorage.getItem(STORAGE_KEY).then((raw) => {\n        const count = (Number(raw) || 0) + 1;\n        AsyncStorage.setItem(STORAGE_KEY, String(count)).catch(() => {});\n        if (count % INTERSTITIAL_EVERY_N_GAMES === 0) {\n          offer(onContinue);\n        } else {\n          onContinue();\n        }\n      });\n    },\n    [offer]\n  );\n\n  return { recordRoundPlayed };\n}\n");
write("App.tsx", "import React, { useCallback, useEffect, useRef } from 'react';\nimport { View } from 'react-native';\nimport { SafeAreaProvider } from 'react-native-safe-area-context';\nimport { StatusBar } from 'expo-status-bar';\nimport * as SplashScreen from 'expo-splash-screen';\nimport { ensureAdsInitialized } from './src/lib/ads';\nimport { installGlobalErrorHandler } from './src/lib/crashReporter';\nimport { MONETIZATION_LIVE } from './src/data/shop';\nimport { initIAP } from './src/lib/iap';\nimport { logEvent } from './src/lib/analytics';\n// Each family's barrel index.js does `export const X = require('./weight.ttf')`\n// for every single weight in one file — Metro evaluates the whole module\n// once anything is imported from it, so importing even one named export\n// from the barrel pulled in all ~18 weights' .ttf files as bundled assets.\n// Importing each weight from its own subpath (confirmed by inspecting the\n// packages: every weight folder has its own index.js requiring only that\n// one file) means only the 7 weights actually used ship in the bundle.\nimport { useFonts } from 'expo-font';\nimport { InterTight_700Bold } from '@expo-google-fonts/inter-tight/700Bold';\nimport { InterTight_800ExtraBold } from '@expo-google-fonts/inter-tight/800ExtraBold';\nimport { InterTight_900Black } from '@expo-google-fonts/inter-tight/900Black';\nimport { SpaceGrotesk_500Medium } from '@expo-google-fonts/space-grotesk/500Medium';\nimport { SpaceGrotesk_600SemiBold } from '@expo-google-fonts/space-grotesk/600SemiBold';\nimport { JetBrainsMono_500Medium } from '@expo-google-fonts/jetbrains-mono/500Medium';\nimport { JetBrainsMono_700Bold } from '@expo-google-fonts/jetbrains-mono/700Bold';\n\nimport { ThemeProvider, useTheme } from './src/theme/ThemeContext';\nimport { I18nProvider } from './src/i18n/i18n';\nimport { AuthProvider, useAuth } from './src/state/auth';\nimport { DiamondsProvider, useDiamonds } from './src/state/diamonds';\nimport { AdBudgetProvider } from './src/state/adBudget';\nimport { StatsProvider, useStats } from './src/state/stats';\nimport { AvatarProvider } from './src/state/avatar';\nimport { SolvedPlayersProvider } from './src/state/solvedPlayers';\nimport { SettingsProvider } from './src/state/settings';\nimport { RewardedInterstitialProvider } from './src/state/rewardedInterstitial';\nimport RootNavigator from './src/navigation/RootNavigator';\nimport AuthScreen from './src/screens/AuthScreen';\nimport LevelUpModal from './src/components/LevelUpModal';\nimport DailyRewardModal from './src/components/DailyRewardModal';\nimport RewardedInterstitialModal from './src/components/RewardedInterstitialModal';\n\nSplashScreen.preventAutoHideAsync().catch(() => {});\n// Installed before ensureAdsInitialized() so it's in place for the very\n// first native callback that could possibly fire.\ninstallGlobalErrorHandler();\n// Kicks off the AdMob SDK init as early as possible, unconditional (not\n// gated on auth/session) — ads.ts itself awaits this same promise before\n// ever creating a RewardedAd/InterstitialAd instance, so by the time a\n// user can reach a \"watch an ad\" button it's long since resolved.\nensureAdsInitialized().catch(() => {});\n\nfunction AppShell() {\n  const { colors, dark } = useTheme();\n  const { session, loading } = useAuth();\n  const { ready: diamondsReady } = useDiamonds();\n  const { ready: statsReady } = useStats();\n  const loggedOpen = useRef(false);\n\n  // Only connects to the store once purchases are actually live — no point\n  // opening a StoreKit connection while ShopScreen still shows \"coming soon\".\n  useEffect(() => {\n    if (session && MONETIZATION_LIVE) initIAP();\n  }, [session]);\n\n  // One 'app_open' per app launch (not per re-render/session refresh) — the\n  // only way to see day-1/day-7 retention later: 'login'/'signup' only fire\n  // once ever per account, so without this there'd be no signal at all for\n  // an already-authenticated user simply coming back on a later day.\n  useEffect(() => {\n    if (session && !loggedOpen.current) {\n      loggedOpen.current = true;\n      logEvent(session.user.id, 'app_open');\n    }\n  }, [session]);\n\n  if (loading) {\n    return <View style={{ flex: 1, backgroundColor: colors.bg }} />;\n  }\n\n  if (!session) {\n    return (\n      <View style={{ flex: 1, backgroundColor: colors.bg }}>\n        <StatusBar style={dark ? 'light' : 'dark'} />\n        <AuthScreen />\n      </View>\n    );\n  }\n\n  if (!diamondsReady || !statsReady) {\n    return <View style={{ flex: 1, backgroundColor: colors.bg }} />;\n  }\n\n  return (\n    <View style={{ flex: 1, backgroundColor: colors.bg }}>\n      <StatusBar style={dark ? 'light' : 'dark'} />\n      <RootNavigator />\n      <LevelUpModal />\n      <DailyRewardModal />\n      <RewardedInterstitialModal />\n    </View>\n  );\n}\n\nexport default function App() {\n  const [fontsLoaded, fontsError] = useFonts({\n    InterTight_700Bold,\n    InterTight_800ExtraBold,\n    InterTight_900Black,\n    SpaceGrotesk_500Medium,\n    SpaceGrotesk_600SemiBold,\n    JetBrainsMono_500Medium,\n    JetBrainsMono_700Bold,\n  });\n  const ready = fontsLoaded || !!fontsError;\n\n  const onLayout = useCallback(async () => {\n    if (ready) await SplashScreen.hideAsync();\n  }, [ready]);\n\n  if (!ready) return null;\n\n  return (\n    <View style={{ flex: 1 }} onLayout={onLayout}>\n      <SafeAreaProvider>\n        <ThemeProvider>\n          <I18nProvider>\n            <AuthProvider>\n              <DiamondsProvider>\n                <AdBudgetProvider>\n                  <StatsProvider>\n                    <AvatarProvider>\n                      <SolvedPlayersProvider>\n                        <SettingsProvider>\n                          <RewardedInterstitialProvider>\n                            <AppShell />\n                          </RewardedInterstitialProvider>\n                        </SettingsProvider>\n                      </SolvedPlayersProvider>\n                    </AvatarProvider>\n                  </StatsProvider>\n                </AdBudgetProvider>\n              </DiamondsProvider>\n            </AuthProvider>\n          </I18nProvider>\n        </ThemeProvider>\n      </SafeAreaProvider>\n    </View>\n  );\n}\n");
write("src/state/adBudget.tsx", "// Single shared source of truth for the daily \"watch a rewarded ad for\n// diamonds\" budget, consumed from the Shop's own ad button as well as the\n// Profil/Settings \"regarder une pub\" offers shown when a purchase fails for\n// lack of diamonds. This used to be two independent implementations (each\n// holding its own local React state, each separately reading/writing the\n// same AsyncStorage key at its own mount time) — if more than one of those\n// screens was mounted at once (very possible: Shop is a Stack screen pushed\n// on top of the still-mounted Tabs underneath), each had a stale view of\n// the other's in-flight changes, so a failed ad on one screen could refund\n// against a state snapshot the other screen had already moved past,\n// silently drifting the persisted daily count upward with nothing to show\n// for it. A single Context instance removes the possibility of two stale\n// copies existing at once.\nimport React, { createContext, useCallback, useContext, useEffect, useState } from 'react';\nimport AsyncStorage from '@react-native-async-storage/async-storage';\nimport { useDiamonds } from './diamonds';\nimport { ADS_LIVE, REWARDED_AD_DIAMONDS, REWARDED_AD_PER_DAY } from '../data/shop';\nimport { showRewardedAd } from '../lib/ads';\n\nconst AD_WATCHED_KEY = 'strikr_ad_watched_v1';\n\nfunction todayStr(): string {\n  return new Date().toISOString().slice(0, 10);\n}\n\ninterface AdBudgetContextValue {\n  watchedToday: number;\n  ready: boolean;\n  watching: boolean;\n  watch: () => Promise<{ success: boolean }>;\n}\n\nconst AdBudgetContext = createContext<AdBudgetContextValue | null>(null);\n\nexport function AdBudgetProvider({ children }: { children: React.ReactNode }) {\n  const { addDiamonds } = useDiamonds();\n  const [watchedToday, setWatchedToday] = useState(0);\n  const [watching, setWatching] = useState(false);\n\n  useEffect(() => {\n    AsyncStorage.getItem(AD_WATCHED_KEY).then((raw) => {\n      if (!raw) return;\n      try {\n        const parsed = JSON.parse(raw);\n        if (parsed.date === todayStr()) setWatchedToday(parsed.count || 0);\n      } catch {\n        // ignore corrupt storage\n      }\n    });\n  }, []);\n\n  const ready = watchedToday < REWARDED_AD_PER_DAY;\n\n  // The count is persisted immediately (not after the ad finishes), so\n  // leaving and re-entering mid-ad can't be used to dodge the daily cap and\n  // double up the reward. It's refunded below on failure (see there for\n  // why) — this still closes that gap, since the refund only happens once\n  // showRewardedAd() actually settles, and leaving before that never lets\n  // it settle in the first place.\n  const watch = useCallback(async (): Promise<{ success: boolean }> => {\n    if (!ready || watching) return { success: false };\n    setWatching(true);\n    setWatchedToday((prev) => {\n      const next = prev + 1;\n      AsyncStorage.setItem(AD_WATCHED_KEY, JSON.stringify({ date: todayStr(), count: next })).catch(() => {});\n      return next;\n    });\n    // ads.ts's showRewardedAd() is designed to always resolve, never\n    // reject, but this is the kind of code path that's already crashed the\n    // app 5 times over — a try/catch here costs nothing and means a\n    // regression there fails the ad request instead of the whole app.\n    let success = true;\n    if (ADS_LIVE) {\n      try {\n        ({ success } = await showRewardedAd());\n      } catch (e) {\n        console.warn('showRewardedAd() rejected', e);\n        success = false;\n      }\n    }\n    setWatching(false);\n    if (!success) {\n      // A failure here means no ad was actually shown (no fill, load\n      // error, timeout) or the reward genuinely wasn't earned — either way\n      // the player got nothing, so this attempt shouldn't burn one of\n      // their daily tries. Without this, a day with poor ad fill silently\n      // exhausts the cap without a single real ad ever being seen.\n      setWatchedToday((prev) => {\n        const next = Math.max(0, prev - 1);\n        AsyncStorage.setItem(AD_WATCHED_KEY, JSON.stringify({ date: todayStr(), count: next })).catch(() => {});\n        return next;\n      });\n      return { success: false };\n    }\n    addDiamonds(REWARDED_AD_DIAMONDS);\n    return { success: true };\n  }, [ready, watching, addDiamonds]);\n\n  return (\n    <AdBudgetContext.Provider value={{ watchedToday, ready, watching, watch }}>\n      {children}\n    </AdBudgetContext.Provider>\n  );\n}\n\nexport function useAdBudget() {\n  const ctx = useContext(AdBudgetContext);\n  if (!ctx) throw new Error('useAdBudget must be used within AdBudgetProvider');\n  return ctx;\n}\n");
write("src/screens/ProfilScreen.tsx", "import React, { useCallback, useState } from 'react';\nimport { ActivityIndicator, Alert, Image, Pressable, ScrollView, Text, View } from 'react-native';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { useFocusEffect, useNavigation } from '@react-navigation/native';\nimport { useTheme } from '../theme/ThemeContext';\nimport { useI18n } from '../i18n/i18n';\nimport { useDiamonds } from '../state/diamonds';\nimport { STREAK_FREEZE_COST, useStats } from '../state/stats';\nimport { useAuth } from '../state/auth';\nimport { useFriends } from '../state/friends';\nimport { useGameHistory } from '../state/appStats';\nimport { useAvatar } from '../state/avatar';\nimport { useAdBudget } from '../state/adBudget';\nimport { pickAndUploadAvatar } from '../lib/avatarUpload';\nimport { BADGES } from '../lib/badges';\nimport AvatarFrame from '../components/AvatarFrame';\nimport { useSolvedPlayers } from '../state/solvedPlayers';\nimport { PLAYERS } from '../data/players';\n\nfunction formatRelativeDay(iso: string, t: (k: string) => string): string {\n  const day = iso.slice(0, 10);\n  const today = new Date().toISOString().slice(0, 10);\n  if (day === today) return t('profil_today');\n  const yesterday = new Date(Date.now() - 86400000).toISOString().slice(0, 10);\n  if (day === yesterday) return t('profil_yesterday');\n  const diffDays = Math.round((new Date(today).getTime() - new Date(day).getTime()) / 86400000);\n  return `-${diffDays}${t('profil_days_ago_suffix')}`;\n}\n\nexport default function ProfilScreen() {\n  const { colors, accent, fonts } = useTheme();\n  const { t, tArray } = useI18n();\n  const { diamonds } = useDiamonds();\n  const { stats, derived, buyStreakFreeze } = useStats();\n  const [freezeMessage, setFreezeMessage] = useState<string | null>(null);\n  const [freezeNotEnough, setFreezeNotEnough] = useState(false);\n  const { ready: adReady, watching: adWatching, watch: watchAd } = useAdBudget();\n  const { user } = useAuth();\n  const { friends, refresh: refreshFriends } = useFriends();\n  const { history, refresh: refreshHistory } = useGameHistory(5);\n  const { avatarUrl, setAvatarUrl, equippedFrame } = useAvatar();\n  const { solvedPlayers } = useSolvedPlayers();\n  const collectionCount = PLAYERS.filter((p) => solvedPlayers.has(p.n)).length;\n  const [avatarUploading, setAvatarUploading] = useState(false);\n  const insets = useSafeAreaInsets();\n  const navigation = useNavigation<any>();\n  const username = user?.user_metadata?.display_name || user?.email?.split('@')[0] || t('leaderboard_you_tag');\n  const ordinals = tArray('ordinals');\n\n  const onChangeAvatar = async () => {\n    if (!user || avatarUploading) return;\n    setAvatarUploading(true);\n    const { url, error } = await pickAndUploadAvatar(user.id);\n    setAvatarUploading(false);\n    if (url) {\n      setAvatarUrl(url);\n    } else if (error === 'permission_denied') {\n      Alert.alert(t('profil_avatar_error_title'), t('profil_avatar_permission_denied'));\n    } else if (error) {\n      // Storage upload failures come back as a raw debug string (status\n      // code, byte size) meant for logs, not players — never shown as-is.\n      Alert.alert(t('profil_avatar_error_title'), t('error_generic'));\n    }\n  };\n\n  // Profil stays mounted in the tab navigator, so without this the history\n  // and friend count would keep showing whatever they were on first load —\n  // stale after finishing a game or adding a friend elsewhere.\n  useFocusEffect(\n    useCallback(() => {\n      refreshHistory();\n      refreshFriends();\n    }, [refreshHistory, refreshFriends])\n  );\n  const badgeStates = BADGES.map((b) => ({ ...b, unlocked: b.isUnlocked(stats, derived.level) }));\n  const unlockedCount = badgeStates.filter((b) => b.unlocked).length;\n\n  return (\n    <View style={{ flex: 1, backgroundColor: colors.bg }}>\n      <View pointerEvents=\"none\" style={{ position: 'absolute', top: -30, right: -30, width: 180, height: 180, backgroundColor: accent.coral, borderRadius: 999, opacity: 0.08 }} />\n      <ScrollView contentContainerStyle={{ paddingTop: insets.top + 6, paddingBottom: 24 }}>\n        <View style={{ paddingHorizontal: 20, alignItems: 'flex-end' }}>\n          <Pressable onPress={() => navigation.getParent()?.navigate('Settings')}>\n            <Text style={{ fontFamily: fonts.displayBold, fontSize: 18, color: colors.ink }}>⚙</Text>\n          </Pressable>\n        </View>\n\n        <View style={{ paddingHorizontal: 20, alignItems: 'center' }}>\n          <Pressable onPress={onChangeAvatar} disabled={avatarUploading}>\n            <AvatarFrame frameId={equippedFrame} size={100}>\n              <View\n                style={{\n                  width: 100, height: 100, borderRadius: 999, backgroundColor: accent.yellow,\n                  borderWidth: 2, borderColor: colors.border, alignItems: 'center', justifyContent: 'center', overflow: 'hidden',\n                }}\n              >\n                {avatarUploading ? (\n                  <ActivityIndicator color={colors.ink} />\n                ) : avatarUrl ? (\n                  <Image source={{ uri: avatarUrl }} style={{ width: '100%', height: '100%' }} />\n                ) : (\n                  <Text style={{ fontFamily: fonts.display, fontSize: 40, color: colors.ink }}>{username.slice(0, 1).toUpperCase()}</Text>\n                )}\n              </View>\n            </AvatarFrame>\n            <View\n              style={{\n                position: 'absolute', bottom: 0, right: 0, width: 30, height: 30, borderRadius: 999,\n                backgroundColor: accent.coral, borderWidth: 2, borderColor: colors.bg, alignItems: 'center', justifyContent: 'center',\n              }}\n            >\n              <Text style={{ fontSize: 13 }}>📷</Text>\n            </View>\n          </Pressable>\n          <Text style={{ fontFamily: fonts.display, fontSize: 22, color: colors.ink, marginTop: 14, letterSpacing: -0.4 }}>{username}</Text>\n          <View style={{ flexDirection: 'row', gap: 6, marginTop: 6 }}>\n            <View style={{ paddingVertical: 3, paddingHorizontal: 9, backgroundColor: colors.border, borderRadius: 999 }}>\n              <Text style={{ fontFamily: fonts.mono, fontSize: 10, color: accent.yellow, letterSpacing: 1 }}>LVL {derived.level}</Text>\n            </View>\n            <View style={{ paddingVertical: 3, paddingHorizontal: 9, backgroundColor: colors.card, borderWidth: 1.5, borderColor: colors.border, borderRadius: 999 }}>\n              <Text style={{ fontFamily: fonts.mono, fontSize: 10, color: colors.ink }}>@{username}</Text>\n            </View>\n          </View>\n          <View style={{ flexDirection: 'row', gap: 8, marginTop: 12 }}>\n            <Pressable\n              onPress={() => navigation.navigate('Friends')}\n              style={{ paddingVertical: 8, paddingHorizontal: 16, backgroundColor: accent.blue, borderWidth: 2, borderColor: colors.border, borderRadius: 999 }}\n            >\n              <Text style={{ fontFamily: fonts.displayBold, fontSize: 11, color: '#fff' }}>🏆 {t('profil_my_friends')} · {friends.length}</Text>\n            </Pressable>\n            <Pressable\n              onPress={() => navigation.getParent()?.navigate('Collection')}\n              style={{ paddingVertical: 8, paddingHorizontal: 16, backgroundColor: accent.coral, borderWidth: 2, borderColor: colors.border, borderRadius: 999 }}\n            >\n              <Text style={{ fontFamily: fonts.displayBold, fontSize: 11, color: '#fff' }}>🃏 {t('profil_my_collection')} · {collectionCount}/{PLAYERS.length}</Text>\n            </Pressable>\n          </View>\n        </View>\n\n        <View style={{ paddingHorizontal: 20, paddingTop: 14 }}>\n          <View style={{ flexDirection: 'row', justifyContent: 'space-between' }}>\n            <Text style={{ fontFamily: fonts.mono, fontSize: 10, color: colors.muted }}>LVL {derived.level} · {derived.xpIntoLevel} XP</Text>\n            <Text style={{ fontFamily: fonts.mono, fontSize: 10, color: colors.muted }}>LVL {derived.level + 1} · {derived.xpForNextLevel}</Text>\n          </View>\n          <View style={{ height: 10, backgroundColor: colors.card, borderWidth: 2, borderColor: colors.border, borderRadius: 999, overflow: 'hidden', marginTop: 4 }}>\n            <View style={{ width: `${Math.round(derived.levelProgress * 100)}%`, height: '100%', backgroundColor: accent.coral }} />\n          </View>\n        </View>\n\n        <View style={{ paddingHorizontal: 20, paddingTop: 14, flexDirection: 'row', gap: 8 }}>\n          {[\n            { bg: colors.card, val: String(stats.solves), label: t('profil_solves'), onPress: undefined },\n            { bg: accent.mint, val: `🔥 ${stats.currentStreak}`, label: t('profil_streak'), onPress: undefined },\n            { bg: accent.pink, val: `💎${diamonds}`, label: t('profil_gems'), onPress: () => navigation.getParent()?.navigate('Shop') },\n          ].map((s, i) => {\n            const Wrapper = s.onPress ? Pressable : View;\n            return (\n              <Wrapper key={i} onPress={s.onPress} style={{ flex: 1, backgroundColor: s.bg, borderWidth: 2, borderColor: colors.border, borderRadius: 12, padding: 9, alignItems: 'center' }}>\n                <Text style={{ fontFamily: fonts.display, fontSize: 20, color: colors.ink }}>{s.val}</Text>\n                <Text style={{ fontFamily: fonts.mono, fontSize: 9, color: colors.muted, letterSpacing: 0.8 }}>{s.label}</Text>\n              </Wrapper>\n            );\n          })}\n        </View>\n\n        <View style={{ paddingHorizontal: 20, paddingTop: 8 }}>\n          <Pressable\n            onPress={() => {\n              const { error } = buyStreakFreeze();\n              const notEnough = error === 'not_enough_diamonds';\n              setFreezeNotEnough(notEnough);\n              setFreezeMessage(notEnough ? t('profil_freeze_not_enough') : t('profil_freeze_bought'));\n            }}\n            style={{ flexDirection: 'row', alignItems: 'center', gap: 10, padding: 10, backgroundColor: colors.card, borderWidth: 2, borderColor: colors.border, borderRadius: 12 }}\n          >\n            <Text style={{ fontSize: 18 }}>🧊</Text>\n            <View style={{ flex: 1 }}>\n              <Text style={{ fontFamily: fonts.displayBold, fontSize: 12, color: colors.ink }}>{t('profil_freeze_title')} × {stats.streakFreezes}</Text>\n              <Text style={{ fontFamily: fonts.mono, fontSize: 9, color: colors.muted, marginTop: 1 }}>{t('profil_freeze_subtitle')}</Text>\n            </View>\n            <View style={{ paddingVertical: 4, paddingHorizontal: 9, backgroundColor: accent.mint, borderWidth: 1.5, borderColor: colors.border, borderRadius: 999 }}>\n              <Text style={{ fontFamily: fonts.mono, fontSize: 10, color: '#1a1a1a' }}>💎{STREAK_FREEZE_COST}</Text>\n            </View>\n          </Pressable>\n          {freezeMessage && (\n            <View style={{ flexDirection: 'row', alignItems: 'center', gap: 8, marginTop: 4 }}>\n              <Text style={{ fontFamily: fonts.bodySemibold, fontSize: 10, color: colors.muted }}>{freezeMessage}</Text>\n              {freezeNotEnough && adReady && (\n                <Pressable\n                  disabled={adWatching}\n                  onPress={async () => {\n                    const { success } = await watchAd();\n                    if (success) {\n                      setFreezeNotEnough(false);\n                      setFreezeMessage(t('shop_ad_confirmed_prefix') + ' +15 💎');\n                    }\n                  }}\n                  style={{ paddingVertical: 3, paddingHorizontal: 8, backgroundColor: accent.mint, borderWidth: 1.5, borderColor: colors.border, borderRadius: 999, opacity: adWatching ? 0.6 : 1 }}\n                >\n                  <Text style={{ fontFamily: fonts.mono, fontSize: 9, color: '#1a1a1a' }}>\n                    {adWatching ? t('shop_ad_loading') : `📺 ${t('shop_ad_title')}`}\n                  </Text>\n                </Pressable>\n              )}\n            </View>\n          )}\n        </View>\n\n        <View style={{ paddingHorizontal: 20, paddingTop: 14 }}>\n          <View style={{ flexDirection: 'row', justifyContent: 'space-between', marginBottom: 6 }}>\n            <Text style={{ fontFamily: fonts.display, fontSize: 13, color: colors.ink }}>{t('profil_badges')} · {unlockedCount}/{badgeStates.length}</Text>\n          </View>\n          <View style={{ flexDirection: 'row', gap: 6, flexWrap: 'wrap', marginBottom: 14 }}>\n            {badgeStates.map((b) =>\n              b.unlocked ? (\n                <View key={b.id} style={{ width: 44, height: 44, borderRadius: 11, backgroundColor: b.bg, borderWidth: 2, borderColor: colors.border, alignItems: 'center', justifyContent: 'center' }}>\n                  <Text style={{ fontSize: 20 }}>{b.icon}</Text>\n                </View>\n              ) : (\n                <View key={b.id} style={{ width: 44, height: 44, borderRadius: 11, backgroundColor: colors.card, borderWidth: 2, borderColor: colors.muted, borderStyle: 'dashed', alignItems: 'center', justifyContent: 'center' }}>\n                  <Text style={{ fontFamily: fonts.display, fontSize: 16, color: colors.muted }}>?</Text>\n                </View>\n              )\n            )}\n          </View>\n\n          <View style={{ flexDirection: 'row', justifyContent: 'space-between', marginBottom: 6 }}>\n            <Text style={{ fontFamily: fonts.display, fontSize: 13, color: colors.ink }}>{t('profil_history')}</Text>\n          </View>\n          {history.length === 0 ? (\n            <Text style={{ fontFamily: fonts.mono, fontSize: 11, color: colors.muted, paddingVertical: 8 }}>{t('profil_no_history')}</Text>\n          ) : (\n            <View style={{ gap: 5 }}>\n              {history.map((h) => (\n                <View key={h.id} style={{ flexDirection: 'row', alignItems: 'center', gap: 9, padding: 8, backgroundColor: h.won ? colors.card : accent.wrongRed, borderWidth: 2, borderColor: colors.border, borderRadius: 12 }}>\n                  <View style={{ width: 28, height: 28, borderRadius: 8, backgroundColor: h.won ? accent.mint : colors.card, borderWidth: 1.5, borderColor: colors.border, alignItems: 'center', justifyContent: 'center' }}>\n                    <Text style={{ fontFamily: fonts.display, fontSize: 12 }}>{h.won ? '✓' : '✕'}</Text>\n                  </View>\n                  <View style={{ flex: 1 }}>\n                    <Text style={{ fontFamily: fonts.displayBold, fontSize: 12, color: colors.ink }}>{h.player_name}</Text>\n                    <Text style={{ fontFamily: fonts.mono, fontSize: 9, color: colors.muted }}>\n                      {h.won\n                        ? `${t('profil_found_at')} ${ordinals[(h.attempt || 1) - 1] || h.attempt} ${t('profil_club')} · +${h.reward_diamonds} 💎`\n                        : t('profil_missed')}\n                    </Text>\n                  </View>\n                  <Text style={{ fontFamily: fonts.mono, fontSize: 9, color: colors.muted }}>{formatRelativeDay(h.created_at, t)}</Text>\n                </View>\n              ))}\n            </View>\n          )}\n        </View>\n      </ScrollView>\n    </View>\n  );\n}\n");
write("src/screens/SettingsScreen.tsx", "import React, { useEffect, useState } from 'react';\nimport { Image, Linking, Modal, Pressable, ScrollView, Text, TextInput, View } from 'react-native';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { useNavigation } from '@react-navigation/native';\nimport * as Clipboard from 'expo-clipboard';\nimport { useTheme } from '../theme/ThemeContext';\nimport { useI18n, LANGS, LANG_LABELS, Lang } from '../i18n/i18n';\nimport { useSettings } from '../state/settings';\nimport { useAuth } from '../state/auth';\nimport { useAvatar } from '../state/avatar';\nimport { useDiamonds } from '../state/diamonds';\nimport { useStats } from '../state/stats';\nimport { supabase } from '../lib/supabase';\nimport { isPlaceholderEmail } from '../lib/username';\nimport { requestNotificationPermission, scheduleDailyReminder, cancelDailyReminder, registerPushToken, clearPushToken } from '../lib/notifications';\nimport { friendlyError } from '../lib/errors';\nimport { AVATAR_FRAMES } from '../data/avatarFrames';\nimport { useAdBudget } from '../state/adBudget';\nimport AvatarFrame from '../components/AvatarFrame';\n\n// Same address already published in privacy-policy.md / terms-of-service.md\n// as the official developer contact — this button is just a shortcut to\n// it, not a new communication surface (opens the device's own Mail app,\n// nothing sent or stored in-app).\nconst SUPPORT_EMAIL = 'caira.sebastien@gmail.com';\n\nfunction ToggleRow({ icon, label, value, onChange }: { icon: string; label: string; value: boolean; onChange: (v: boolean) => void }) {\n  const { colors, accent } = useTheme();\n  const { fonts } = useTheme();\n  return (\n    <Pressable\n      onPress={() => onChange(!value)}\n      style={{ flexDirection: 'row', alignItems: 'center', gap: 10, padding: 12, backgroundColor: colors.card, borderWidth: 2, borderColor: colors.border, borderRadius: 12 }}\n    >\n      <Text style={{ fontSize: 18 }}>{icon}</Text>\n      <Text style={{ flex: 1, fontFamily: fonts.displayBold, fontSize: 13, color: colors.ink }}>{label}</Text>\n      <View style={{ width: 42, height: 24, borderRadius: 999, backgroundColor: value ? accent.mint : colors.track, borderWidth: 2, borderColor: colors.border, justifyContent: 'center' }}>\n        <View style={{ width: 16, height: 16, borderRadius: 999, backgroundColor: colors.border, marginLeft: value ? 22 : 2 }} />\n      </View>\n    </Pressable>\n  );\n}\n\nexport default function SettingsScreen() {\n  const { colors, accent, fonts, dark, setDark } = useTheme();\n  const { t, lang, setLang } = useI18n();\n  const { settings, setSoundEnabled, setHapticsEnabled, setNotificationsEnabled } = useSettings();\n  const { user, signOut } = useAuth();\n  const { avatarUrl, ownedFrames, equippedFrame, buyFrame, equipFrame } = useAvatar();\n  const [frameMessage, setFrameMessage] = useState<string | null>(null);\n  const [frameNotEnough, setFrameNotEnough] = useState(false);\n  const { ready: adReady, watching: adWatching, watch: watchAd } = useAdBudget();\n  const { syncLocalDelta } = useDiamonds();\n  const { derived } = useStats();\n  const insets = useSafeAreaInsets();\n  const navigation = useNavigation<any>();\n\n  const [langMenuOpen, setLangMenuOpen] = useState(false);\n  const [helpOpen, setHelpOpen] = useState(false);\n  const [legalOpen, setLegalOpen] = useState(false);\n  const [recoveryEmail, setRecoveryEmail] = useState('');\n  const [recoveryBusy, setRecoveryBusy] = useState(false);\n  const [recoveryMessage, setRecoveryMessage] = useState<string | null>(null);\n  const [newPassword, setNewPassword] = useState('');\n  const [newPasswordConfirm, setNewPasswordConfirm] = useState('');\n  const [passwordBusy, setPasswordBusy] = useState(false);\n  const [passwordMessage, setPasswordMessage] = useState<string | null>(null);\n  const [newUsername, setNewUsername] = useState('');\n  const [usernameBusy, setUsernameBusy] = useState(false);\n  const [usernameMessage, setUsernameMessage] = useState<string | null>(null);\n  const [referralCode, setReferralCode] = useState<string | null>(null);\n  const [referredBy, setReferredBy] = useState<string | null>(null);\n  const [referralCopied, setReferralCopied] = useState(false);\n  const [referralInput, setReferralInput] = useState('');\n  const [referralBusy, setReferralBusy] = useState(false);\n  const [referralMessage, setReferralMessage] = useState<string | null>(null);\n  const [deleteConfirmOpen, setDeleteConfirmOpen] = useState(false);\n  const [deleteBusy, setDeleteBusy] = useState(false);\n  const [deleteError, setDeleteError] = useState<string | null>(null);\n\n  const username = user?.user_metadata?.display_name || user?.email?.split('@')[0] || '';\n  const hasRealEmail = !isPlaceholderEmail(user?.email);\n\n  useEffect(() => {\n    if (!user) return;\n    supabase\n      .from('profiles')\n      .select('referral_code, referred_by')\n      .eq('id', user.id)\n      .single()\n      .then(({ data }) => {\n        setReferralCode(data?.referral_code ?? null);\n        setReferredBy(data?.referred_by ?? null);\n      });\n  }, [user]);\n\n  const copyReferralCode = async () => {\n    if (!referralCode) return;\n    await Clipboard.setStringAsync(referralCode);\n    setReferralCopied(true);\n    setTimeout(() => setReferralCopied(false), 1500);\n  };\n\n  const redeemReferralCode = async () => {\n    const code = referralInput.trim();\n    if (!code) return;\n    setReferralBusy(true);\n    setReferralMessage(null);\n    const { error } = await supabase.rpc('redeem_referral_code', { code_arg: code });\n    setReferralBusy(false);\n    if (error) {\n      const reason =\n        error.message.includes('own_code') ? t('settings_referral_error_own') :\n        error.message.includes('already_redeemed') ? t('settings_referral_error_used') :\n        t('settings_referral_error_invalid');\n      setReferralMessage(reason);\n      return;\n    }\n    syncLocalDelta(200);\n    setReferredBy('me');\n    setReferralInput('');\n    setReferralMessage(t('settings_referral_redeemed'));\n  };\n\n  const deleteAccount = async () => {\n    setDeleteBusy(true);\n    setDeleteError(null);\n    const { error } = await supabase.rpc('delete_account');\n    if (error) {\n      setDeleteBusy(false);\n      setDeleteError(t('settings_delete_account_error'));\n      return;\n    }\n    await supabase.auth.signOut().catch(() => {});\n    setDeleteBusy(false);\n    setDeleteConfirmOpen(false);\n  };\n\n  const onToggleNotifications = async (v: boolean) => {\n    if (!v) {\n      setNotificationsEnabled(false);\n      await cancelDailyReminder();\n      if (user) await clearPushToken(user.id);\n      return;\n    }\n    const granted = await requestNotificationPermission();\n    if (!granted) {\n      setNotificationsEnabled(false);\n      return;\n    }\n    setNotificationsEnabled(true);\n    await scheduleDailyReminder(t('notif_reminder_title'), t('notif_reminder_body'));\n    if (user) await registerPushToken(user.id);\n  };\n\n  const saveRecoveryEmail = async () => {\n    if (!recoveryEmail.trim()) return;\n    setRecoveryBusy(true);\n    setRecoveryMessage(null);\n    const { error } = await supabase.auth.updateUser({ email: recoveryEmail.trim() });\n    setRecoveryBusy(false);\n    setRecoveryMessage(error ? friendlyError(error, t('error_generic')) : t('auth_recovery_email_saved'));\n  };\n\n  const saveUsername = async () => {\n    const trimmed = newUsername.trim();\n    if (!trimmed) return;\n    setUsernameMessage(null);\n    if (trimmed.length < 3) {\n      setUsernameMessage(t('auth_error_username_short'));\n      return;\n    }\n    setUsernameBusy(true);\n    if (trimmed.toLowerCase() !== username.toLowerCase()) {\n      const { data: taken } = await supabase.rpc('is_username_taken', { check_username: trimmed });\n      if (taken) {\n        setUsernameBusy(false);\n        setUsernameMessage(t('auth_error_username_taken'));\n        return;\n      }\n    }\n    const { error: metaError } = await supabase.auth.updateUser({ data: { display_name: trimmed } });\n    if (!metaError && user) {\n      await supabase.from('profiles').update({ display_name: trimmed }).eq('id', user.id);\n    }\n    setUsernameBusy(false);\n    if (metaError) {\n      setUsernameMessage(friendlyError(metaError, t('error_generic')));\n      return;\n    }\n    setNewUsername('');\n    setUsernameMessage(t('settings_username_saved'));\n  };\n\n  const savePassword = async () => {\n    if (!newPassword) return;\n    setPasswordMessage(null);\n    if (newPassword !== newPasswordConfirm) {\n      setPasswordMessage(t('settings_password_mismatch'));\n      return;\n    }\n    setPasswordBusy(true);\n    const { error } = await supabase.auth.updateUser({ password: newPassword });\n    setPasswordBusy(false);\n    if (error) {\n      setPasswordMessage(friendlyError(error, t('error_generic')));\n      return;\n    }\n    setNewPassword('');\n    setNewPasswordConfirm('');\n    setPasswordMessage(t('settings_password_saved'));\n  };\n\n  return (\n    <View style={{ flex: 1, backgroundColor: colors.bg, paddingTop: insets.top + 14 }}>\n      <View style={{ paddingHorizontal: 20, flexDirection: 'row', alignItems: 'center', gap: 10 }}>\n        <Pressable onPress={() => navigation.goBack()}>\n          <Text style={{ fontFamily: fonts.displayBold, fontSize: 22, color: colors.ink }}>←</Text>\n        </Pressable>\n        <Text style={{ fontFamily: fonts.display, fontSize: 24, color: colors.ink, letterSpacing: -0.4 }}>{t('settings_title')}</Text>\n      </View>\n\n      <ScrollView contentContainerStyle={{ padding: 20, gap: 16 }}>\n        <View>\n          <Text style={{ fontFamily: fonts.mono, fontSize: 10, color: colors.muted, letterSpacing: 1.4, marginBottom: 6 }}>{t('settings_account')}</Text>\n          <View style={{ flexDirection: 'row', alignItems: 'center', gap: 10, padding: 12, backgroundColor: colors.card, borderWidth: 2, borderColor: colors.border, borderRadius: 12 }}>\n            <AvatarFrame frameId={equippedFrame} size={36}>\n              <View style={{ width: 36, height: 36, borderRadius: 999, backgroundColor: accent.yellow, borderWidth: 1.5, borderColor: colors.border, alignItems: 'center', justifyContent: 'center', overflow: 'hidden' }}>\n                {avatarUrl ? (\n                  <Image source={{ uri: avatarUrl }} style={{ width: '100%', height: '100%' }} />\n                ) : (\n                  <Text style={{ fontFamily: fonts.display, fontSize: 14 }}>{username.slice(0, 1).toUpperCase()}</Text>\n                )}\n              </View>\n            </AvatarFrame>\n            <View style={{ flex: 1 }}>\n              <Text style={{ fontFamily: fonts.displayBold, fontSize: 13, color: colors.ink }}>{username}</Text>\n            </View>\n          </View>\n\n          <View style={{ marginTop: 6, padding: 12, backgroundColor: colors.card, borderWidth: 2, borderColor: colors.border, borderRadius: 12, gap: 8 }}>\n            <Text style={{ fontFamily: fonts.displayBold, fontSize: 12, color: colors.ink }}>{t('settings_frames_title')}</Text>\n            <ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={{ gap: 10 }}>\n              <Pressable onPress={() => equipFrame(null)} style={{ alignItems: 'center', gap: 4 }}>\n                <View style={{ width: 52, height: 52, borderRadius: 999, backgroundColor: colors.bg, borderWidth: 2, borderColor: equippedFrame === null ? accent.coral : colors.border, alignItems: 'center', justifyContent: 'center' }}>\n                  <Text style={{ fontFamily: fonts.display, fontSize: 11, color: colors.muted }}>{t('settings_frames_none')}</Text>\n                </View>\n              </Pressable>\n              {AVATAR_FRAMES.map((f) => {\n                const leveledIn = f.unlockLevel !== undefined && derived.level >= f.unlockLevel;\n                const available = ownedFrames.includes(f.id) || leveledIn;\n                const equipped = equippedFrame === f.id;\n                return (\n                  <Pressable\n                    key={f.id}\n                    onPress={() => {\n                      if (available) {\n                        equipFrame(f.id);\n                        return;\n                      }\n                      if (f.milestoneOnly) {\n                        setFrameNotEnough(false);\n                        setFrameMessage(t('settings_frames_milestone_locked'));\n                        return;\n                      }\n                      if (f.unlockLevel !== undefined) {\n                        setFrameNotEnough(false);\n                        setFrameMessage(t('settings_frames_level_locked_prefix') + ' ' + f.unlockLevel);\n                        return;\n                      }\n                      const { error } = buyFrame(f.id);\n                      const notEnough = error === 'not_enough_diamonds';\n                      setFrameNotEnough(notEnough);\n                      if (notEnough) setFrameMessage(t('settings_frames_not_enough'));\n                      else setFrameMessage(null);\n                    }}\n                    style={{ alignItems: 'center', gap: 4 }}\n                  >\n                    <AvatarFrame frameId={f.id} size={44}>\n                      <View style={{ width: 44, height: 44, borderRadius: 999, backgroundColor: colors.card, borderWidth: equipped ? 2 : 0, borderColor: accent.coral, alignItems: 'center', justifyContent: 'center' }}>\n                        {!available && <Text style={{ fontSize: 14 }}>🔒</Text>}\n                      </View>\n                    </AvatarFrame>\n                    <Text style={{ fontFamily: fonts.mono, fontSize: 8, color: colors.muted }}>\n                      {available\n                        ? t(f.labelKey)\n                        : f.milestoneOnly\n                        ? '🔒'\n                        : f.unlockLevel !== undefined\n                        ? `LVL ${f.unlockLevel}`\n                        : `💎${f.cost}`}\n                    </Text>\n                  </Pressable>\n                );\n              })}\n            </ScrollView>\n            {frameMessage && (\n              <View style={{ flexDirection: 'row', alignItems: 'center', gap: 8, marginTop: 4 }}>\n                <Text style={{ fontFamily: fonts.bodySemibold, fontSize: 11, color: colors.muted }}>{frameMessage}</Text>\n                {frameNotEnough && adReady && (\n                  <Pressable\n                    disabled={adWatching}\n                    onPress={async () => {\n                      const { success } = await watchAd();\n                      if (success) {\n                        setFrameNotEnough(false);\n                        setFrameMessage(t('shop_ad_confirmed_prefix') + ' +15 💎');\n                      }\n                    }}\n                    style={{ paddingVertical: 3, paddingHorizontal: 8, backgroundColor: accent.mint, borderWidth: 1.5, borderColor: colors.border, borderRadius: 999, opacity: adWatching ? 0.6 : 1 }}\n                  >\n                    <Text style={{ fontFamily: fonts.mono, fontSize: 9, color: '#1a1a1a' }}>\n                      {adWatching ? t('shop_ad_loading') : `📺 ${t('shop_ad_title')}`}\n                    </Text>\n                  </Pressable>\n                )}\n              </View>\n            )}\n          </View>\n\n          <View style={{ marginTop: 6, padding: 12, backgroundColor: colors.card, borderWidth: 2, borderColor: colors.border, borderRadius: 12, gap: 8 }}>\n            <Text style={{ fontFamily: fonts.displayBold, fontSize: 12, color: colors.ink }}>{t('settings_username_title')}</Text>\n            <TextInput\n              value={newUsername}\n              onChangeText={setNewUsername}\n              placeholder={username || t('settings_username_placeholder')}\n              placeholderTextColor={colors.muted}\n              autoCapitalize=\"none\"\n              autoCorrect={false}\n              style={{\n                fontFamily: fonts.bodySemibold, fontSize: 13, color: colors.ink,\n                backgroundColor: colors.bg, borderWidth: 2, borderColor: colors.border, borderRadius: 10,\n                paddingVertical: 9, paddingHorizontal: 12,\n              }}\n            />\n            <Pressable\n              onPress={saveUsername}\n              disabled={usernameBusy}\n              style={{ paddingVertical: 9, backgroundColor: accent.blue, borderRadius: 10, alignItems: 'center', opacity: usernameBusy ? 0.6 : 1 }}\n            >\n              <Text style={{ fontFamily: fonts.displayBold, fontSize: 12, color: '#fff' }}>{t('settings_username_save')}</Text>\n            </Pressable>\n            {usernameMessage && (\n              <Text style={{ fontFamily: fonts.bodySemibold, fontSize: 11, color: colors.muted }}>{usernameMessage}</Text>\n            )}\n          </View>\n\n          <View style={{ marginTop: 6, padding: 12, backgroundColor: colors.card, borderWidth: 2, borderColor: colors.border, borderRadius: 12, gap: 8 }}>\n            <Text style={{ fontFamily: fonts.displayBold, fontSize: 12, color: colors.ink }}>{t('settings_referral_title')}</Text>\n            <Text style={{ fontFamily: fonts.bodySemibold, fontSize: 11, color: colors.muted, lineHeight: 15 }}>{t('settings_referral_subtitle')}</Text>\n            {referralCode && (\n              <Pressable\n                onPress={copyReferralCode}\n                style={{ flexDirection: 'row', alignItems: 'center', gap: 6, padding: 10, backgroundColor: colors.bg, borderWidth: 2, borderColor: colors.muted, borderStyle: 'dashed', borderRadius: 10 }}\n              >\n                <Text style={{ fontSize: 14 }}>🔗</Text>\n                <Text style={{ flex: 1, fontFamily: fonts.displayBold, fontSize: 14, color: colors.ink, letterSpacing: 2 }}>{referralCode}</Text>\n                <View style={{ paddingVertical: 4, paddingHorizontal: 9, backgroundColor: colors.border, borderRadius: 999 }}>\n                  <Text style={{ fontFamily: fonts.mono, fontSize: 10, color: colors.bg }}>{referralCopied ? '✓' : t('friends_copy')}</Text>\n                </View>\n              </Pressable>\n            )}\n            {!referredBy && (\n              <>\n                <TextInput\n                  value={referralInput}\n                  onChangeText={setReferralInput}\n                  placeholder={t('settings_referral_input_placeholder')}\n                  placeholderTextColor={colors.muted}\n                  autoCapitalize=\"characters\"\n                  autoCorrect={false}\n                  style={{\n                    fontFamily: fonts.bodySemibold, fontSize: 13, color: colors.ink,\n                    backgroundColor: colors.bg, borderWidth: 2, borderColor: colors.border, borderRadius: 10,\n                    paddingVertical: 9, paddingHorizontal: 12,\n                  }}\n                />\n                <Pressable\n                  onPress={redeemReferralCode}\n                  disabled={referralBusy}\n                  style={{ paddingVertical: 9, backgroundColor: accent.blue, borderRadius: 10, alignItems: 'center', opacity: referralBusy ? 0.6 : 1 }}\n                >\n                  <Text style={{ fontFamily: fonts.displayBold, fontSize: 12, color: '#fff' }}>{t('settings_referral_redeem')}</Text>\n                </Pressable>\n              </>\n            )}\n            {referralMessage && (\n              <Text style={{ fontFamily: fonts.bodySemibold, fontSize: 11, color: colors.muted }}>{referralMessage}</Text>\n            )}\n          </View>\n\n          <View style={{ marginTop: 6, padding: 12, backgroundColor: colors.card, borderWidth: 2, borderColor: colors.border, borderRadius: 12, gap: 8 }}>\n            {hasRealEmail ? (\n              <Text style={{ fontFamily: fonts.bodySemibold, fontSize: 12, color: colors.ink }}>\n                {t('auth_recovery_email_current_prefix')} {user?.email}\n              </Text>\n            ) : (\n              <>\n                <Text style={{ fontFamily: fonts.displayBold, fontSize: 12, color: colors.ink }}>{t('auth_recovery_email_title')}</Text>\n                <TextInput\n                  value={recoveryEmail}\n                  onChangeText={setRecoveryEmail}\n                  placeholder={t('auth_recovery_email_placeholder')}\n                  placeholderTextColor={colors.muted}\n                  autoCapitalize=\"none\"\n                  autoCorrect={false}\n                  keyboardType=\"email-address\"\n                  style={{\n                    fontFamily: fonts.bodySemibold, fontSize: 13, color: colors.ink,\n                    backgroundColor: colors.bg, borderWidth: 2, borderColor: colors.border, borderRadius: 10,\n                    paddingVertical: 9, paddingHorizontal: 12,\n                  }}\n                />\n                <Pressable\n                  onPress={saveRecoveryEmail}\n                  disabled={recoveryBusy}\n                  style={{ paddingVertical: 9, backgroundColor: accent.blue, borderRadius: 10, alignItems: 'center', opacity: recoveryBusy ? 0.6 : 1 }}\n                >\n                  <Text style={{ fontFamily: fonts.displayBold, fontSize: 12, color: '#fff' }}>{t('auth_recovery_email_save')}</Text>\n                </Pressable>\n                {recoveryMessage && (\n                  <Text style={{ fontFamily: fonts.bodySemibold, fontSize: 11, color: colors.muted }}>{recoveryMessage}</Text>\n                )}\n              </>\n            )}\n          </View>\n\n          <View style={{ marginTop: 6, padding: 12, backgroundColor: colors.card, borderWidth: 2, borderColor: colors.border, borderRadius: 12, gap: 8 }}>\n            <Text style={{ fontFamily: fonts.displayBold, fontSize: 12, color: colors.ink }}>{t('settings_password_title')}</Text>\n            <TextInput\n              value={newPassword}\n              onChangeText={setNewPassword}\n              placeholder={t('settings_password_new_placeholder')}\n              placeholderTextColor={colors.muted}\n              secureTextEntry\n              style={{\n                fontFamily: fonts.bodySemibold, fontSize: 13, color: colors.ink,\n                backgroundColor: colors.bg, borderWidth: 2, borderColor: colors.border, borderRadius: 10,\n                paddingVertical: 9, paddingHorizontal: 12,\n              }}\n            />\n            <TextInput\n              value={newPasswordConfirm}\n              onChangeText={setNewPasswordConfirm}\n              placeholder={t('settings_password_confirm_placeholder')}\n              placeholderTextColor={colors.muted}\n              secureTextEntry\n              style={{\n                fontFamily: fonts.bodySemibold, fontSize: 13, color: colors.ink,\n                backgroundColor: colors.bg, borderWidth: 2, borderColor: colors.border, borderRadius: 10,\n                paddingVertical: 9, paddingHorizontal: 12,\n              }}\n            />\n            <Pressable\n              onPress={savePassword}\n              disabled={passwordBusy}\n              style={{ paddingVertical: 9, backgroundColor: accent.blue, borderRadius: 10, alignItems: 'center', opacity: passwordBusy ? 0.6 : 1 }}\n            >\n              <Text style={{ fontFamily: fonts.displayBold, fontSize: 12, color: '#fff' }}>{t('settings_password_save')}</Text>\n            </Pressable>\n            {passwordMessage && (\n              <Text style={{ fontFamily: fonts.bodySemibold, fontSize: 11, color: colors.muted }}>{passwordMessage}</Text>\n            )}\n          </View>\n        </View>\n\n        <View>\n          <Text style={{ fontFamily: fonts.mono, fontSize: 10, color: colors.muted, letterSpacing: 1.4, marginBottom: 6 }}>{t('settings_prefs')}</Text>\n          <View style={{ gap: 6 }}>\n            <ToggleRow icon=\"🔔\" label={t('settings_notif')} value={settings.notificationsEnabled} onChange={onToggleNotifications} />\n            <ToggleRow icon=\"🔊\" label={t('settings_sound')} value={settings.soundEnabled} onChange={setSoundEnabled} />\n            <ToggleRow icon=\"📳\" label={t('settings_haptics')} value={settings.hapticsEnabled} onChange={setHapticsEnabled} />\n\n            <Pressable\n              onPress={() => setLangMenuOpen(true)}\n              style={{ flexDirection: 'row', alignItems: 'center', gap: 10, padding: 12, backgroundColor: colors.card, borderWidth: 2, borderColor: colors.border, borderRadius: 12 }}\n            >\n              <Text style={{ fontSize: 18 }}>🌐</Text>\n              <Text style={{ flex: 1, fontFamily: fonts.displayBold, fontSize: 13, color: colors.ink }}>{t('settings_language')}</Text>\n              <Text style={{ fontFamily: fonts.mono, fontSize: 11, color: colors.muted }}>{LANG_LABELS[lang]} ▾</Text>\n            </Pressable>\n\n            <Pressable\n              onPress={() => setDark(!dark)}\n              style={{ flexDirection: 'row', alignItems: 'center', gap: 10, padding: 12, backgroundColor: colors.card, borderWidth: 2, borderColor: colors.border, borderRadius: 12 }}\n            >\n              <Text style={{ fontSize: 18 }}>🌙</Text>\n              <Text style={{ flex: 1, fontFamily: fonts.displayBold, fontSize: 13, color: colors.ink }}>{t('settings_dark_mode')}</Text>\n              <View style={{ width: 42, height: 24, borderRadius: 999, backgroundColor: dark ? accent.mint : colors.track, borderWidth: 2, borderColor: colors.border, justifyContent: 'center' }}>\n                <View style={{ width: 16, height: 16, borderRadius: 999, backgroundColor: colors.border, marginLeft: dark ? 22 : 2 }} />\n              </View>\n            </Pressable>\n          </View>\n        </View>\n\n        <View>\n          <Text style={{ fontFamily: fonts.mono, fontSize: 10, color: colors.muted, letterSpacing: 1.4, marginBottom: 6 }}>{t('settings_support')}</Text>\n          <View style={{ gap: 6 }}>\n            <Pressable\n              onPress={() => setHelpOpen(true)}\n              style={{ flexDirection: 'row', alignItems: 'center', gap: 10, padding: 12, backgroundColor: colors.card, borderWidth: 2, borderColor: colors.border, borderRadius: 12 }}\n            >\n              <Text style={{ flex: 1, fontFamily: fonts.displaySemibold, fontSize: 13, color: colors.ink }}>{t('settings_help')}</Text>\n              <Text style={{ color: colors.muted }}>→</Text>\n            </Pressable>\n            <Pressable\n              onPress={() => setLegalOpen(true)}\n              style={{ flexDirection: 'row', alignItems: 'center', gap: 10, padding: 12, backgroundColor: colors.card, borderWidth: 2, borderColor: colors.border, borderRadius: 12 }}\n            >\n              <Text style={{ flex: 1, fontFamily: fonts.displaySemibold, fontSize: 13, color: colors.ink }}>{t('settings_legal')}</Text>\n              <Text style={{ color: colors.muted }}>→</Text>\n            </Pressable>\n          </View>\n        </View>\n\n        <Pressable\n          onPress={() => signOut()}\n          style={{ padding: 14, backgroundColor: colors.card, borderWidth: 2, borderColor: accent.coral, borderRadius: 12, alignItems: 'center' }}\n        >\n          <Text style={{ fontFamily: fonts.displayBold, fontSize: 13, color: accent.coral }}>{t('settings_logout')}</Text>\n        </Pressable>\n\n        <Pressable\n          onPress={() => {\n            setDeleteError(null);\n            setDeleteConfirmOpen(true);\n          }}\n          style={{ padding: 12, alignItems: 'center' }}\n        >\n          <Text style={{ fontFamily: fonts.bodySemibold, fontSize: 12, color: colors.muted, textDecorationLine: 'underline' }}>\n            {t('settings_delete_account')}\n          </Text>\n        </Pressable>\n      </ScrollView>\n\n      <Modal visible={deleteConfirmOpen} transparent animationType=\"fade\" onRequestClose={() => setDeleteConfirmOpen(false)}>\n        <Pressable style={{ flex: 1, backgroundColor: 'rgba(0,0,0,.45)', alignItems: 'center', justifyContent: 'center', padding: 24 }} onPress={() => !deleteBusy && setDeleteConfirmOpen(false)}>\n          <Pressable style={{ backgroundColor: colors.bg, borderWidth: 2.5, borderColor: accent.coral, borderRadius: 20, padding: 22, maxWidth: 340, width: '100%' }}>\n            <Text style={{ fontFamily: fonts.display, fontSize: 16, color: colors.ink, marginBottom: 10 }}>{t('settings_delete_account_confirm_title')}</Text>\n            <Text style={{ fontFamily: fonts.body, fontSize: 13, color: colors.ink, lineHeight: 19 }}>{t('settings_delete_account_confirm_body')}</Text>\n            {deleteError && (\n              <Text style={{ marginTop: 10, fontFamily: fonts.bodySemibold, fontSize: 12, color: accent.coral }}>{deleteError}</Text>\n            )}\n            <Pressable\n              onPress={deleteAccount}\n              disabled={deleteBusy}\n              style={{ marginTop: 18, paddingVertical: 12, backgroundColor: accent.coral, borderRadius: 12, alignItems: 'center', opacity: deleteBusy ? 0.6 : 1 }}\n            >\n              <Text style={{ fontFamily: fonts.displayBold, fontSize: 13, color: '#fff' }}>\n                {deleteBusy ? '…' : t('settings_delete_account_confirm_button')}\n              </Text>\n            </Pressable>\n            <Pressable\n              onPress={() => setDeleteConfirmOpen(false)}\n              disabled={deleteBusy}\n              style={{ marginTop: 10, paddingVertical: 10, alignItems: 'center' }}\n            >\n              <Text style={{ fontFamily: fonts.bodySemibold, fontSize: 12, color: colors.muted }}>{t('settings_delete_account_cancel')}</Text>\n            </Pressable>\n          </Pressable>\n        </Pressable>\n      </Modal>\n\n      <Modal visible={langMenuOpen} transparent animationType=\"fade\" onRequestClose={() => setLangMenuOpen(false)}>\n        <Pressable style={{ flex: 1, backgroundColor: 'rgba(0,0,0,.4)', justifyContent: 'center', padding: 24 }} onPress={() => setLangMenuOpen(false)}>\n          <View style={{ backgroundColor: colors.card, borderWidth: 2, borderColor: colors.border, borderRadius: 12, overflow: 'hidden' }}>\n            {LANGS.map((l: Lang) => (\n              <Pressable\n                key={l}\n                onPress={() => {\n                  setLang(l);\n                  setLangMenuOpen(false);\n                }}\n                style={{\n                  flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', gap: 10,\n                  padding: 14, backgroundColor: l === lang ? accent.yellow : colors.card,\n                  borderBottomWidth: 1, borderBottomColor: 'rgba(0,0,0,.08)',\n                }}\n              >\n                <Text style={{ fontFamily: fonts.displayBold, fontSize: 12, color: colors.ink }}>{LANG_LABELS[l]}</Text>\n                {l === lang && <Text style={{ color: colors.ink }}>✓</Text>}\n              </Pressable>\n            ))}\n          </View>\n        </Pressable>\n      </Modal>\n\n      <Modal visible={helpOpen} transparent animationType=\"fade\" onRequestClose={() => setHelpOpen(false)}>\n        <Pressable style={{ flex: 1, backgroundColor: 'rgba(0,0,0,.45)', alignItems: 'center', justifyContent: 'center', padding: 24 }} onPress={() => setHelpOpen(false)}>\n          <View style={{ backgroundColor: colors.bg, borderWidth: 2.5, borderColor: colors.border, borderRadius: 20, padding: 22, maxWidth: 340, width: '100%' }}>\n            <Text style={{ fontFamily: fonts.display, fontSize: 16, color: colors.ink, marginBottom: 12 }}>{t('settings_help_title')}</Text>\n            <ScrollView style={{ maxHeight: 320 }}>\n              <Text style={{ fontFamily: fonts.body, fontSize: 13, color: colors.ink, lineHeight: 19 }}>{t('settings_help_body')}</Text>\n            </ScrollView>\n            <Pressable\n              onPress={() => Linking.openURL(`mailto:${SUPPORT_EMAIL}?subject=${encodeURIComponent('STRIKR - Support')}`)}\n              style={{ marginTop: 14, paddingVertical: 10, backgroundColor: colors.card, borderWidth: 2, borderColor: colors.border, borderRadius: 12, alignItems: 'center' }}\n            >\n              <Text style={{ fontFamily: fonts.displayBold, fontSize: 13, color: colors.ink }}>✉️ {t('settings_contact_button')}</Text>\n            </Pressable>\n            <Pressable onPress={() => setHelpOpen(false)} style={{ marginTop: 10, paddingVertical: 10, backgroundColor: accent.coral, borderRadius: 12, alignItems: 'center' }}>\n              <Text style={{ fontFamily: fonts.display, fontSize: 13, color: '#fff' }}>{t('settings_help_close')}</Text>\n            </Pressable>\n          </View>\n        </Pressable>\n      </Modal>\n\n      <Modal visible={legalOpen} transparent animationType=\"fade\" onRequestClose={() => setLegalOpen(false)}>\n        <Pressable style={{ flex: 1, backgroundColor: 'rgba(0,0,0,.45)', alignItems: 'center', justifyContent: 'center', padding: 24 }} onPress={() => setLegalOpen(false)}>\n          <View style={{ backgroundColor: colors.bg, borderWidth: 2.5, borderColor: colors.border, borderRadius: 20, padding: 22, maxWidth: 340, width: '100%' }}>\n            <Text style={{ fontFamily: fonts.display, fontSize: 16, color: colors.ink, marginBottom: 12 }}>{t('settings_legal_title')}</Text>\n            <ScrollView style={{ maxHeight: 320 }}>\n              <Text style={{ fontFamily: fonts.body, fontSize: 13, color: colors.ink, lineHeight: 19 }}>{t('settings_legal_body')}</Text>\n            </ScrollView>\n            <Pressable onPress={() => setLegalOpen(false)} style={{ marginTop: 18, paddingVertical: 10, backgroundColor: accent.coral, borderRadius: 12, alignItems: 'center' }}>\n              <Text style={{ fontFamily: fonts.display, fontSize: 13, color: '#fff' }}>{t('settings_legal_close')}</Text>\n            </Pressable>\n          </View>\n        </Pressable>\n      </Modal>\n    </View>\n  );\n}\n");
write("src/screens/ShopScreen.tsx", "import React, { useCallback, useState } from 'react';\nimport { Modal, Pressable, ScrollView, Text, View } from 'react-native';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { useNavigation } from '@react-navigation/native';\nimport { useTheme } from '../theme/ThemeContext';\nimport { useI18n } from '../i18n/i18n';\nimport { useDiamonds } from '../state/diamonds';\nimport { useAuth } from '../state/auth';\nimport { useAdBudget } from '../state/adBudget';\nimport { SHOP_PACKAGES, REWARDED_AD_DIAMONDS, REWARDED_AD_PER_DAY, ADS_LIVE, MONETIZATION_LIVE } from '../data/shop';\nimport HardShadowBox from '../components/HardShadowBox';\nimport { logEvent } from '../lib/analytics';\nimport { purchasePackage } from '../lib/iap';\n\nexport default function ShopScreen() {\n  const { colors, accent, fonts } = useTheme();\n  const { t } = useI18n();\n  const { diamonds, addDiamonds } = useDiamonds();\n  const { user } = useAuth();\n  const insets = useSafeAreaInsets();\n  const navigation = useNavigation<any>();\n  const { watchedToday: adWatchedToday, ready: adReady, watching: adWatching, watch: watchAdBudget } = useAdBudget();\n\n  const [confirmation, setConfirmation] = useState<{ text: string; simulated: boolean } | null>(null);\n  const [adError, setAdError] = useState(false);\n  const [buying, setBuying] = useState<string | null>(null);\n  const [purchaseError, setPurchaseError] = useState(false);\n\n  const buyPackage = useCallback(\n    async (id: string, diamondsAmount: number) => {\n      if (buying) return;\n      setBuying(id);\n      setPurchaseError(false);\n      const { success, error } = await purchasePackage(id);\n      setBuying(null);\n      if (!success) {\n        // A user-initiated cancel isn't an error — App Review flagged the\n        // opposite problem (a failed/hung purchase giving zero feedback at\n        // all), so every other outcome now surfaces something on screen\n        // instead of silently doing nothing.\n        if (error !== 'cancelled') setPurchaseError(true);\n        return;\n      }\n      addDiamonds(diamondsAmount);\n      logEvent(user?.id, 'shop_purchase', { package_id: id, diamonds: diamondsAmount });\n      // MONETIZATION_LIVE means this was a real, actually-charged purchase —\n      // showing the \"simulated purchase\" note here (as this unconditionally\n      // did before) would tell a paying customer their money wasn't really\n      // taken.\n      const prefix = t(MONETIZATION_LIVE ? 'shop_purchase_confirmed_real_prefix' : 'shop_purchase_confirmed_prefix');\n      setConfirmation({ text: prefix + ' +' + diamondsAmount + ' 💎', simulated: !MONETIZATION_LIVE });\n    },\n    [addDiamonds, t, user, buying]\n  );\n\n  // Daily-cap tracking, the actual showRewardedAd() call, and the\n  // increment/refund dance all live in useAdBudget() now (see\n  // src/state/adBudget.tsx) — shared with the Profil/Settings \"regarder une\n  // pub\" offers, so there's exactly one place counting today's watches\n  // instead of two independent copies that could drift apart.\n  const watchAd = useCallback(async () => {\n    setAdError(false);\n    const { success } = await watchAdBudget();\n    if (!success) {\n      setAdError(true);\n      return;\n    }\n    setConfirmation({ text: t('shop_ad_confirmed_prefix') + ' +' + REWARDED_AD_DIAMONDS + ' 💎', simulated: !ADS_LIVE });\n  }, [watchAdBudget, t]);\n\n  return (\n    <View style={{ flex: 1, backgroundColor: colors.bg, paddingTop: insets.top + 14 }}>\n      <View style={{ paddingHorizontal: 20, flexDirection: 'row', alignItems: 'center', gap: 10 }}>\n        <Pressable onPress={() => navigation.goBack()}>\n          <Text style={{ fontFamily: fonts.displayBold, fontSize: 22, color: colors.ink }}>←</Text>\n        </Pressable>\n        <Text style={{ fontFamily: fonts.display, fontSize: 24, color: colors.ink, letterSpacing: -0.4, flex: 1 }}>{t('shop_title')}</Text>\n        <View style={{ paddingVertical: 5, paddingHorizontal: 10, backgroundColor: accent.mint, borderWidth: 2, borderColor: colors.border, borderRadius: 999 }}>\n          <Text style={{ fontFamily: fonts.displayBold, fontSize: 12, color: '#1a1a1a' }}>💎 {diamonds}</Text>\n        </View>\n      </View>\n\n      <ScrollView contentContainerStyle={{ padding: 20, gap: 10 }}>\n        <HardShadowBox bg=\"#1a1a1a\" shadowColor={accent.yellow} radius={14} offset={3}>\n          <Pressable\n            onPress={watchAd}\n            disabled={!adReady || adWatching}\n            style={{ padding: 14, flexDirection: 'row', alignItems: 'center', gap: 12, opacity: !adReady ? 0.55 : 1 }}\n          >\n            <Text style={{ fontSize: 26 }}>📺</Text>\n            <View style={{ flex: 1 }}>\n              <Text style={{ fontFamily: fonts.display, fontSize: 14, color: '#fff' }}>\n                {adWatching ? t('shop_ad_loading') : `${t('shop_ad_title')} +${REWARDED_AD_DIAMONDS} 💎`}\n              </Text>\n              <Text style={{ fontFamily: fonts.body, fontSize: 11, color: 'rgba(255,255,255,.7)', marginTop: 2 }}>\n                {adReady ? `${t('shop_ad_sub')} · ${adWatchedToday}/${REWARDED_AD_PER_DAY}` : t('shop_ad_exhausted')}\n              </Text>\n            </View>\n          </Pressable>\n        </HardShadowBox>\n        {adError && (\n          <Text style={{ fontFamily: fonts.body, fontSize: 11, color: colors.muted, textAlign: 'center' }}>\n            {t('shop_ad_unavailable')}\n          </Text>\n        )}\n\n        {MONETIZATION_LIVE ? (\n          SHOP_PACKAGES.map((p) => (\n            <HardShadowBox key={p.id} bg={p.popular ? accent.yellow : colors.card} radius={14} offset={3}>\n              <Pressable\n                onPress={() => buyPackage(p.id, p.diamonds + (p.bonus || 0))}\n                disabled={!!buying}\n                style={{ padding: 14, flexDirection: 'row', alignItems: 'center', gap: 12, opacity: buying && buying !== p.id ? 0.5 : 1 }}\n              >\n                <Text style={{ fontSize: 30 }}>💎</Text>\n                <View style={{ flex: 1 }}>\n                  <Text style={{ fontFamily: fonts.display, fontSize: 16, color: colors.ink }}>\n                    {p.diamonds}\n                    {p.bonus ? ` +${p.bonus}` : ''}\n                  </Text>\n                  {p.popular && (\n                    <Text style={{ fontFamily: fonts.mono, fontSize: 9, color: colors.ink, letterSpacing: 1, marginTop: 1 }}>\n                      {t('shop_popular')}\n                    </Text>\n                  )}\n                </View>\n                <View style={{ paddingVertical: 8, paddingHorizontal: 14, backgroundColor: p.popular ? '#1a1a1a' : accent.coral, borderRadius: 10 }}>\n                  <Text style={{ fontFamily: fonts.displayBold, fontSize: 13, color: '#fff' }}>{p.priceLabel}</Text>\n                </View>\n              </Pressable>\n            </HardShadowBox>\n          ))\n        ) : null}\n        {purchaseError && (\n          <Text style={{ fontFamily: fonts.body, fontSize: 11, color: colors.muted, textAlign: 'center' }}>\n            {t('shop_purchase_error')}\n          </Text>\n        )}\n        {!MONETIZATION_LIVE && (\n          <View style={{ alignItems: 'center', padding: 24 }}>\n            <Text style={{ fontSize: 32 }}>🚧</Text>\n            <Text style={{ fontFamily: fonts.display, fontSize: 15, color: colors.ink, marginTop: 10, textAlign: 'center' }}>\n              {t('shop_coming_soon_title')}\n            </Text>\n            <Text style={{ fontFamily: fonts.body, fontSize: 12, color: colors.muted, marginTop: 6, textAlign: 'center', lineHeight: 17 }}>\n              {t('shop_coming_soon_body')}\n            </Text>\n          </View>\n        )}\n      </ScrollView>\n\n      <Modal visible={!!confirmation} transparent animationType=\"fade\" onRequestClose={() => setConfirmation(null)}>\n        <Pressable style={{ flex: 1, backgroundColor: 'rgba(0,0,0,.45)', alignItems: 'center', justifyContent: 'center', padding: 24 }} onPress={() => setConfirmation(null)}>\n          <View style={{ backgroundColor: colors.bg, borderWidth: 2.5, borderColor: colors.border, borderRadius: 20, padding: 22, maxWidth: 320, width: '100%', alignItems: 'center' }}>\n            <Text style={{ fontSize: 34 }}>✅</Text>\n            <Text style={{ fontFamily: fonts.display, fontSize: 15, color: colors.ink, marginTop: 8, textAlign: 'center' }}>{confirmation?.text}</Text>\n            {confirmation?.simulated && (\n              <Text style={{ fontFamily: fonts.body, fontSize: 11, color: colors.muted, marginTop: 6, textAlign: 'center' }}>{t('shop_test_mode_note')}</Text>\n            )}\n            <Pressable onPress={() => setConfirmation(null)} style={{ marginTop: 16, paddingVertical: 10, paddingHorizontal: 24, backgroundColor: accent.coral, borderRadius: 12 }}>\n              <Text style={{ fontFamily: fonts.displayBold, fontSize: 13, color: '#fff' }}>OK</Text>\n            </Pressable>\n          </View>\n        </Pressable>\n      </Modal>\n    </View>\n  );\n}\n");
remove("src/game/useWatchAdForDiamonds.ts");
